  function buildMockQuestions(resource, externalQuestions=[]) {
    const requested = /mega/i.test(resource?.title || '') || resource?.id === 'test-mega-paper-ii' ? 200 : 30;
    const normalizedExternal = Array.isArray(externalQuestions) ? externalQuestions.map((question,index) => ({
      id:String(question.id || `live-q-${index+1}`),
      text:String(question.text || question.question || `Question ${index+1}`),
      options:Array.isArray(question.options) ? question.options.map(String) : [],
      answer:Number.isInteger(question.answer) ? question.answer : Number(question.correctIndex ?? 0),
      marks:Number(question.marks || 1)
    })).filter(question => question.options.length >= 2) : [];
    if (normalizedExternal.length) return normalizedExternal;
    return Array.from({length:requested}, (_,index) => {
      const seed=mockQuestionSeeds[index % mockQuestionSeeds.length];
      const set=Math.floor(index / mockQuestionSeeds.length)+1;
      return {...seed,id:`${resource?.id || 'mock'}-q-${index+1}`,marks:1,text:set===1?seed.text:`${seed.text} (Practice Set ${set})`};
    });
  }

