  function analyticsBar(label,value,detail='',tone='blue'){
    return `<div class="analytics-bar-row"><div><strong>${escapeHtml(label)}</strong><small>${escapeHtml(detail)}</small></div><div class="analytics-track"><span class="${tone}" style="width:${Math.max(0,Math.min(100,Number(value)||0))}%"></span></div><b>${escapeHtml(value)}%</b></div>`;
  }

  function analyticsTrend(values,labels=[]){
    const max=Math.max(...values,1);
    return `<div class="analytics-trend">${values.map((value,index)=>`<div><span style="height:${Math.max(8,Math.round((value/max)*100))}%"></span><small>${escapeHtml(labels[index]||String(index+1))}</small></div>`).join('')}</div>`;
  }

  function studentAnalyticsWorkspace(){
    return `${heading('Learning Command Center','Real learning signals become one clear study decision — attempts, accuracy, reading, watching, revision and readiness.')}
      <section class="analytics-hero">
        <div><span class="eyebrow">STUDENT ANALYTICS</span><h2>Your preparation, connected across every learning action.</h2><p>Metrics remain tied to exact resource IDs and owned attempts. The production adapter replaces package sample states with real Firebase data.</p><div class="analytics-hero-actions">${button('Open Mistake Book','primary','data-go="success/results"')}${button('Continue weak topic','secondary','data-open="note-child-development"')}</div></div>
        <aside><div class="analytics-ring" style="--value:64"><strong>64%</strong><small>Selection readiness</small></div><p><strong>Next best action:</strong> Revise development principles, then reattempt the chapter test.</p></aside>
      </section>
      <div class="analytics-kpi-grid">${kpi('Mock attempts','9','Owned attempts')}${kpi('Average accuracy','76%','+8 points this week')}${kpi('Study time','6.4 hrs','Notes + video + practice')}${kpi('Current streak','3 days','Best: 9 days')}${kpi('Notes progress','68%','4 revision items')}${kpi('Video completion','42%','Resume IntelliPlayer')}</div>
      <div class="analytics-layout">
        <section class="analytics-card span-2"><header><div><span class="eyebrow">WEEKLY PERFORMANCE</span><h2>Accuracy and activity trend</h2></div><span class="state-badge open">REAL-ID READY</span></header>${analyticsTrend([42,58,51,72,64,78,76],['Mon','Tue','Wed','Thu','Fri','Sat','Sun'])}<footer><span>Attempts: 3</span><span>Questions: 230</span><span>Revision: 41 min</span></footer></section>
        <section class="analytics-card"><header><div><span class="eyebrow">WEAK AREA</span><h2>Child Development</h2></div></header><div class="priority-score"><strong>58%</strong><small>Needs targeted revision</small></div>${analyticsBar('Development principles',52,'3 incorrect','orange')}${analyticsBar('Learning theories',78,'Strong','green')}${analyticsBar('Inclusive education',64,'Review once','blue')}</section>
        <section class="analytics-card"><header><div><span class="eyebrow">LEARNING MIX</span><h2>How you studied</h2></div></header><div class="analytics-donut-row"><div class="analytics-donut"></div><ul><li><i class="navy"></i>Notes 42%</li><li><i class="orange"></i>Practice 36%</li><li><i class="green"></i>Video 22%</li></ul></div></section>
        <section class="analytics-card span-2"><header><div><span class="eyebrow">SUBJECT PERFORMANCE</span><h2>Strength, progress and next action</h2></div></header>${analyticsBar('Child Development & Pedagogy',76,'9 attempts • 68% note progress','orange')}${analyticsBar('Mathematics',54,'2 notes • no test yet','blue')}${analyticsBar('Social Science',61,'Current Affairs active','green')}${analyticsBar('English',0,'No published resource in this package','grey')}</section>
        <section class="analytics-card"><header><div><span class="eyebrow">AI STUDY PLAN</span><h2>Evidence-led next steps</h2></div></header><ol class="analytics-plan"><li>Revise Growth vs Development for 20 minutes.</li><li>Attempt 10 targeted CDP questions.</li><li>Review wrong answers after a 24-hour gap.</li></ol></section>
      </div>`;
  }

  function renderSuccessExperience(context){
    if(context==='analytics') return studentAnalyticsWorkspace();
    if(context==='leaderboard'){
      return `${heading('Leaderboard','Daily, weekly and challenge rankings use privacy-safe learner identity.')}<section class="leaderboard-layout"><article class="leaderboard-own"><span>Your rank</span><strong>#18</strong><small>Top 12% • 760 XP this week</small></article><div class="leaderboard-list">${[['1','A. Sharma','1,420 XP'],['2','M. Joshi','1,280 XP'],['3','R. Kumar','1,190 XP'],['18','You','760 XP']].map(row=>`<article class="${row[1]==='You'?'own':''}"><span>${row[0]}</span><strong>${row[1]}</strong><small>${row[2]}</small></article>`).join('')}</div></section>`;
    }
    if(context==='achievements'){
      return `${heading('Achievements','Meaningful badges are earned through verified activity or explicit Admin awards.')}<div class="achievement-grid">${experienceBadges.map(badge=>`<article class="achievement-card ${badge.state}"><span>${badge.icon}</span><h3>${escapeHtml(badge.title)}</h3><p>${escapeHtml(badge.copy)}</p><small>${badge.state==='unlocked'?'Unlocked':'Progress tracked'}</small></article>`).join('')}</div>`;
    }
    if(context==='wall'){
      return `${heading('Success Wall','Only approved, verified and consented stories appear.')}<div class="success-wall-grid">${successStories.map(story=>`<article class="success-story ${story.featured?'featured':''}"><span class="success-avatar">${escapeHtml(story.name.slice(0,1))}</span><div><h3>${escapeHtml(story.result)}</h3><p>${escapeHtml(story.name)} • ${escapeHtml(story.copy)}</p></div></article>`).join('')}</div>`;
    }
    if(context==='history'){
      return `${heading('Learning History','Real resource, attempt and revision activity remains attached to exact IDs.')}<div class="activity-feed">${experienceActivity.map(item=>`<article><span>↻</span><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.copy)}</p><small>${escapeHtml(item.time)}</small></div></article>`).join('')}</div>`;
    }
    if(context==='results'){
      return `${heading('Results','Results and review remain bound to the owned attempt and exact test ID.')}<div class="kpi-grid">${kpi('Latest score','24 / 30','CDP Growth test')}${kpi('Accuracy','80%','+8 points')}${kpi('Strong area','Learning theories','Stable')}${kpi('Revision priority','Development principles','3 questions')}</div><div class="experience-two-col">${infoCard('Mistake Book','Three incorrect concepts are ready for targeted revision.')}${infoCard('Recommended next','Review the note checkpoint and reattempt after 24 hours.')}</div>`;
    }
    return `${heading('Selection Progress','See momentum, readiness and the next best action — not vanity metrics.')}<div class="kpi-grid">${kpi('Readiness','64%','Across learn, practice and revise')}${kpi('Weekly XP','760','Level 7')}${kpi('Streak','3 days','Best: 9 days')}${kpi('Challenge','67%','CDP Accuracy')}</div>${renderStudentExperienceFeed()}`;
  }

  function adminContentKind(context){
    return ({notes:'note',videos:'video',tests:'mock-test','current-affairs':'current-affairs',roadmaps:'roadmap',live:'live-replay'})[context]||'resource';
  }

  function adminExperienceKind(context){
    return ({events:'event',campaigns:'campaign',missions:'mission',challenges:'challenge',badges:'badge',notifications:'notification','mentor-messages':'mentor-message','success-wall':'success-story',settings:'experience-settings'})[context]||'event';
  }

  function adminField(label,control,help=''){
    return `<label class="admin-form-field"><span>${escapeHtml(label)}</span>${control}${help?`<small>${escapeHtml(help)}</small>`:''}</label>`;
  }
  function adminInput(name,type='text',value='',attrs=''){
    return `<input name="${name}" type="${type}" value="${escapeHtml(value)}" ${attrs}>`;
  }
  function adminSelect(name,options,value=''){
    return `<select name="${name}">${options.map(option=>`<option ${String(option)===String(value)?'selected':''}>${escapeHtml(option)}</option>`).join('')}</select>`;
  }
  function adminTextarea(name,value='',attrs=''){
    return `<textarea name="${name}" ${attrs}>${escapeHtml(value)}</textarea>`;
  }
  function adminFormSection(title,copy,content){
    return `<section class="admin-form-section"><header><h3>${escapeHtml(title)}</h3><p>${escapeHtml(copy)}</p></header><div class="admin-form-grid">${content}</div></section>`;
  }

