  function openAdminStudio(kind,recordId=''){
    const definition=adminStudioDefinition(kind);
    openModal(definition.title,definition.copy,`<form id="adminStudioForm" class="admin-studio-form" data-kind="${escapeHtml(kind)}" data-record-id="${escapeHtml(recordId)}">${definition.body}<div class="admin-form-safety"><strong>Operational UI + controlled integration boundary</strong><p>This standalone package validates forms, previews, local workflow state and audit history. Real Firebase, Storage, payment and entitlement writes activate only after repository integration and security-rule verification.</p></div></form>`,`${button('Cancel','secondary','data-action="close-modal"')}${button('Validate & preview','secondary','data-action="admin-preview"')}${button(recordId?'Save update':'Save controlled draft','primary','data-action="submit-admin-form"')}`);
  }

  function adminFormValues(form) {
    const values={};
    const data=new FormData(form);
    data.forEach((value,key)=>{
      const normalized=value instanceof File ? value.name : String(value);
      if(Object.prototype.hasOwnProperty.call(values,key))values[key]=`${values[key]},${normalized}`;
      else values[key]=normalized;
    });
    form.querySelectorAll('input[type="checkbox"]').forEach(input=>{
      values[input.name||input.parentElement?.textContent?.trim()||'checkbox']=Boolean(input.checked);
    });
    return values;
  }

  function upsertAdminRecord(list,record) {
    const index=list.findIndex(item=>item.id===record.id);
    if(index>=0)list[index]={...list[index],...record};
    else list.unshift(record);
  }


  function previewBulkAccessRows(values={}) {
    const input=String(values.learners||'').split(/[\n,;]+/).map(item=>item.trim()).filter(Boolean);
    const seen=new Set();
    const rows=input.map(learner=>{
      const normalized=learner.toLowerCase();
      const identity=learners.find(item=>item.id===learner||String(item.email).toLowerCase()===normalized);
      let decision='VALID';let detail='Registered identity and exact scope ready.';
      if(seen.has(normalized)){decision='DUPLICATE';detail='Duplicate row inside this batch.';}
      else if(!identity){decision='UNKNOWN';detail='No registered learner identity; create a secure invite instead.';}
      else {
        const existing=findDuplicateGrant(identity.id,values.scope||'ITEM',values.target||'');
        const revoked=state.adminGrants.find(item=>item.learnerId===identity.id&&item.scope===(values.scope||'ITEM')&&item.target===(values.target||'')&&effectiveGrantStatus(item)==='Revoked');
        if(existing){decision='DUPLICATE';detail=`Existing grant ${existing.id}.`;}
        else if(revoked){decision='CONFLICT';detail=`Revoked grant ${revoked.id} requires restore/review.`;}
      }
      seen.add(normalized);
      return {learner,learnerId:identity?.id||'',email:identity?.email||(normalized.includes('@')?normalized:''),decision,scope:values.scope||'ITEM',target:values.target||'',detail};
    });
    return {
      rows,
      summary:{
        valid:rows.filter(row=>row.decision==='VALID').length,
        duplicate:rows.filter(row=>row.decision==='DUPLICATE').length,
        conflict:rows.filter(row=>row.decision==='CONFLICT').length,
        unknown:rows.filter(row=>row.decision==='UNKNOWN').length
      }
    };
  }

  async function saveAdminEntityFromForm(kind,values,title,recordId='') {
    const now=new Date().toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
    const id=recordId||`${kind}-${Date.now()}`;
    const resourceKinds=['resource','note','video','mock-test','current-affairs','roadmap','live-replay'];
    let adapterResult=Promise.resolve({ok:true,mode:'ui-draft'});

    if(resourceKinds.includes(kind)){
      const typeMap={resource:values.resourceType||'resource',note:'note',video:'video','mock-test':'test','current-affairs':'current-affairs',roadmap:'roadmap','live-replay':values.sessionType==='Replay'?'replay':'live'};
      upsertAdminRecord(state.adminResources,{id,title,type:typeMap[kind],subject:values.subject||'Unmapped',access:values.access||'FREE',status:values.status||'Draft',updated:now,owner:state.session.email||'Admin',canonicalRoute:values.canonicalRoute||''});
      adapterResult=adapter.saveAdminResource?.({id,kind,values,title});
      recordAdminAudit(recordId?'UPDATE_RESOURCE':'SAVE_RESOURCE_DRAFT',id,`${title} • ${values.status||'Draft'}`);
    } else if(kind==='grant'){
      const learnerInput=values.learner||'learner-rakesh';
      const learnerRecord=learners.find(item=>item.id===learnerInput||item.email===learnerInput);
      const sourceMap={'Admin manual':'admin_manual','Scholarship':'scholarship','Trial':'trial','Offline payment verified':'offline_payment'};
      const grantSource=sourceMap[values.source]||'admin_manual';
      const result=createCanonicalGrant({learnerId:learnerRecord?.id||learnerInput,scope:values.scope||'ITEM',target:values.target||'',source:grantSource,until:values.expiresAt||'No expiry',reason:values.reason||''});
      if(!result.ok){recordAdminAudit('DUPLICATE_GRANT_BLOCKED',result.grant.id,`${values.scope||'ITEM'} → ${values.target||''}`,'Review');return {id:result.grant.id,duplicate:true};}
      adapterResult=adapter.saveAccessGrant?.({id:result.grant.id,...values,source:grantSource,learnerUid:learnerRecord?.uid||'',learnerEmail:learnerRecord?.email||(/@/.test(learnerInput)?learnerInput:''),learnerName:learnerRecord?.name||''});
      recordAdminAudit('GRANT_ACCESS',result.grant.id,`${values.scope||'ITEM'} → ${values.target||''}`);
    } else if(kind==='bulk'){
      const rows=String(values.learners||'').split(/\n+/).map(value=>value.trim()).filter(Boolean).map((learner,index)=>({learner,decision:index===0?'VALID':index===1?'DUPLICATE':'VALID',scope:values.scope,target:values.target}));
      state.adminBulkPreview={rows,summary:{valid:rows.filter(row=>row.decision==='VALID').length,duplicate:rows.filter(row=>row.decision==='DUPLICATE').length,conflict:0,unknown:0},createdAt:now};
      adapterResult=adapter.previewBulkAccess?.({rows,values});
      recordAdminAudit('BULK_ACCESS_PREVIEW',id,`${rows.length} learner rows previewed`,'Review');
    } else if(kind==='product'||kind==='plan'){
      upsertAdminRecord(state.adminProducts,{id,name:values.name||title,code:values.code||'CUSTOM',productType:values.productType||'PLAN',target:values.target||values.code||'',price:Number(values.price||0),discountPrice:Number(values.discountPrice||values.price||0),validity:values.validity?String(values.validity).match(/days|ongoing|event/i)?String(values.validity):`${values.validity} days`:'Ongoing',scope:values.modules||values.scope||`${values.productType||'PLAN'} → ${values.target||values.code||'Exact mapping'}`,purchaseMode:values.purchaseMode||'Request only',publicVisible:values.visibleSurfaces==='Public + Student',studentVisible:['Student','Public + Student'].includes(values.visibleSurfaces),status:values.productStatus||values.checkout||values.planStatus||'Draft'});
      adapterResult=adapter.saveAccessProduct?.({id,...values});
      recordAdminAudit(recordId?'UPDATE_PRODUCT':'CREATE_PRODUCT',id,values.name||title);
    } else if(kind==='access-key'){
      const maxUses=Number(values.redemptions||1);
      const code=`AN-${String(values.scope||'ITEM').slice(0,4)}-${Date.now().toString().slice(-6)}`.toUpperCase();
      upsertAdminRecord(state.adminKeys,{id,code,type:values.keyType||'Campaign key',scope:values.scope||'ITEM',target:values.target||'',usage:`0 / ${maxUses}`,uses:0,maxUses,assignedEmail:values.assignedEmail||'',expires:values.expiry?new Date(values.expiry).toLocaleString('en-IN'):'No expiry',status:'Active',createdAt:now,lastEvent:'Created'});
      adapterResult=adapter.saveAccessKey?.({id,code,...values});
      recordAdminAudit('CREATE_ACCESS_KEY',id,`${values.scope||'ITEM'} → ${values.target||''}`);
    } else if(kind==='invite'){
      const inviteCode=`AN-INV-${Date.now().toString(36).toUpperCase()}`;
      const inviteLink=`${location.origin}${location.pathname}#student/home/redeem-access?invite=${encodeURIComponent(inviteCode)}`;
      const defaultInviteExpiry=new Date(Date.now()+7*24*60*60*1000).toLocaleString('en-IN');
      upsertAdminRecord(state.adminInvites,{id,email:values.email||'',scope:values.scope||'ITEM',target:values.target||'',sent:'Not sent',status:'Pending',inviteCode,inviteLink,expires:values.expiry?new Date(values.expiry).toLocaleString('en-IN'):defaultInviteExpiry,lastEvent:'Created'});
      adapterResult=adapter.saveAccessInvite?.({id,inviteCode,inviteLink,...values});
      recordAdminAudit('CREATE_ACCESS_INVITE',id,values.email||'Invite');
    } else if(kind==='payment'){
      upsertAdminRecord(state.adminPayments,{id,learner:values.learner||'',email:values.email||'',amount:Number(values.amount||0),method:values.method||'UPI',reference:values.reference||'',date:now,status:values.paymentStatus||'Pending review'});
      adapterResult=adapter.saveAdminOperation?.({kind,id,values});
      recordAdminAudit('RECORD_PAYMENT',id,`${values.reference||''} • ₹${values.amount||0}`);
    } else if(kind==='coupon'){
      upsertAdminRecord(state.adminCoupons,{id,code:values.code||'COUPON',discount:values.discountType==='Flat amount'?`₹${values.discount||0}`:`${values.discount||0}%`,audience:values.audience||'All learners',redemptions:`0 / ${values.maxRedemptions||1}`,validity:values.expiry||'No expiry',status:values.couponStatus||'Active'});
      adapterResult=adapter.saveAdminOperation?.({kind,id,values});
      recordAdminAudit('CREATE_COUPON',id,values.code||'Coupon');
    } else if(kind==='refund'){
      upsertAdminRecord(state.adminRefunds,{id,paymentId:values.paymentId||'',learner:values.learner||'',amount:Number(values.amount||0),reason:values.reason||'',requested:now,status:values.refundStatus||'Pending review'});
      adapterResult=adapter.saveAdminOperation?.({kind,id,values});
      recordAdminAudit('REVIEW_REFUND',id,`${values.paymentId||''} • ${values.refundStatus||'Pending review'}`,'Review');
    } else if(kind==='mentor-profile'){
      upsertAdminRecord(state.adminMentors,{id,name:values.name||title,email:values.email||'',specialization:values.specialization||'',learners:0,capacity:Number(values.capacity||25),availability:values.availability||'Available',status:values.mentorStatus||'Active'});
      adapterResult=adapter.saveAdminOperation?.({kind,id,values});
      recordAdminAudit(recordId?'UPDATE_MENTOR':'CREATE_MENTOR',id,values.name||title);
    } else if(kind==='crm-lead'){
      upsertAdminRecord(state.adminCrm,{id,name:values.name||title,contact:values.contact||'',source:values.source||'Website',stage:values.stage||'New enquiry',owner:values.owner||'Unassigned',followUp:values.followUp||'Not scheduled'});
      adapterResult=adapter.saveAdminOperation?.({kind,id,values});
      recordAdminAudit(recordId?'UPDATE_CRM_LEAD':'CREATE_CRM_LEAD',id,values.name||title);
    } else if(kind==='learner-profile'){
      adapterResult=adapter.saveAdminOperation?.({kind,id,values});
      recordAdminAudit(recordId?'UPDATE_LEARNER':'CREATE_LEARNER_PROFILE',id,values.email||values.name||title);
    } else if(kind.endsWith('-settings')){
      const key=kind.replace('-settings','');
      state.adminSettings[key]={...(state.adminSettings[key]||{}),...values};
      adapterResult=adapter.saveAdminSettings?.({section:key,values});
      recordAdminAudit('UPDATE_SETTINGS',key,`${key} settings updated`);
    } else {
      adapterResult=adapter.saveAdminOperation?.({kind,id,values});
      recordAdminAudit('SAVE_ADMIN_ENTITY',id,`${kind} • ${title}`);
    }

    persistAdminOperations();
    try { await adapterResult; } catch (_) {}
    return {id};
  }

  async function submitAdminStudio(previewOnly=false){
    const form=document.getElementById('adminStudioForm');
    if(!form)return;
    if(!form.reportValidity())return;
    const kind=form.dataset.kind||'resource';
    const recordId=form.dataset.recordId||'';
    const values=adminFormValues(form);
    const title=values.title||values.name||values.code||kind.replace(/-/g,' ');
    if(previewOnly){
      const summary=Object.entries(values).filter(([,value])=>value!==''&&value!==false).slice(0,8).map(([key,value])=>`<li><strong>${escapeHtml(key.replace(/([A-Z])/g,' $1'))}</strong><span>${escapeHtml(String(value))}</span></li>`).join('');
      openModal('Responsive Admin preview','Validated data, device coverage and release safety for this exact operation.',`<div class="admin-preview-grid"><article><span>DESKTOP</span><strong>Two rails + full workspace</strong><small>Forms use 2–3 columns and unclipped modal content.</small></article><article><span>TABLET</span><strong>Compact navigation</strong><small>Form grid collapses to two columns; tables remain horizontally scrollable.</small></article><article><span>MOBILE</span><strong>Bottom dock + safe sheet</strong><small>44px touch targets and no clipped actions.</small></article></div><section class="admin-preview-summary"><h3>${escapeHtml(title)}</h3><ul>${summary}</ul></section><div class="continuity-note"><strong>Production boundary</strong><p>Preview is complete. The standalone package stores a controlled local operation; production uses audited server-side adapters.</p></div>`,button('Back to form','primary',`data-action="reopen-admin-form" data-kind="${escapeHtml(kind)}"`));
      return;
    }
    const result=await saveAdminEntityFromForm(kind,values,title,recordId);
    closeModal();
    renderAll();
    toast(`${title} saved in the controlled Admin workflow`,'✓');
    return result;
  }

  function renderAdminExperience(context){
    const title=ADMIN_CONTEXTS.experience.find(x=>x[0]===context)?.[1]||'Experience Studio';
    const kind=adminExperienceKind(context);
    const buttonLabels={event:'Create event',campaign:'Create campaign',mission:'Create mission',challenge:'Create challenge',badge:'Create badge',notification:'Create notification','mentor-message':'Create mentor message','success-story':'Create success story','experience-settings':'Edit settings'};
    let content='';
    if(context==='events') content=`<div class="experience-admin-grid">${experienceEvents.map(event=>`<article class="experience-admin-card"><header><span>${experienceStatusLabel(event.status)}</span><strong>${escapeHtml(event.priority)}</strong></header><h3>${escapeHtml(event.title)}</h3><p>${escapeHtml(event.type)} • ${escapeHtml(event.startLabel)} • ${escapeHtml(event.planType)}</p><footer><button data-admin-demo="event">Edit</button><button data-action="admin-archive">Archive</button></footer></article>`).join('')}</div>`;
    else if(context==='campaigns') content=`<div class="experience-admin-grid">${experienceCampaigns.map(item=>`<article class="experience-admin-card"><header>${statusPill(item.status)}</header><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.audience)} • ${escapeHtml(item.channel)} • ${escapeHtml(item.window)}</p></article>`).join('')}</div>`;
    else if(context==='missions') content=`<div class="experience-admin-grid"><article class="experience-admin-card"><header>${statusPill('Active')}</header><h3>${escapeHtml(experienceMission.title)}</h3><p>${escapeHtml(experienceMission.copy)} • ${experienceMission.xp} XP</p></article></div>`;
    else if(context==='challenges') content=`<div class="experience-admin-grid"><article class="experience-admin-card"><header>${statusPill('Active')}</header><h3>${escapeHtml(experienceChallenge.title)}</h3><p>${escapeHtml(experienceChallenge.copy)} • ${escapeHtml(experienceChallenge.ends)}</p></article></div>`;
    else if(context==='badges') content=`<div class="achievement-grid">${experienceBadges.map(item=>`<article class="achievement-card ${item.state}"><span>${item.icon}</span><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.copy)}</p></article>`).join('')}</div>`;
    else if(context==='notifications') content=`${adminTable(['Title','Audience','Status'],experienceNotifications.map(item=>`<tr><td><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.body)}</small></td><td>${escapeHtml(item.audience)}</td><td>${statusPill(item.status)}</td></tr>`))}`;
    else if(context==='mentor-messages') content=`<div class="experience-admin-grid">${mentorMessages.map(item=>`<article class="experience-admin-card"><header>${statusPill(item.status)}</header><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.copy)} • ${escapeHtml(item.mentor)}</p></article>`).join('')}</div>`;
    else if(context==='success-wall') content=`<div class="success-wall-grid">${successStories.map(item=>`<article class="success-story ${item.featured?'featured':''}"><span class="success-avatar">${escapeHtml(item.name.slice(0,1))}</span><div><h3>${escapeHtml(item.result)}</h3><p>${escapeHtml(item.name)} • ${escapeHtml(item.copy)}</p></div></article>`).join('')}</div>`;
    else content=`<div class="dashboard-grid">${infoCard('Heartbeat policy','Real event first; clean hidden state when empty.')}${infoCard('Momentum controls','Mission, streak, XP, level and badge visibility.')}${infoCard('Community controls','Challenges, leaderboard, activity and success wall.')}${infoCard('Responsive contract','Desktop, tablet, mobile, orientation and 200% zoom gates.')}</div>`;
    els.page.innerHTML=`${heading(title,'Admin-controlled Experience Engine with one event model, central CTA resolution and no fake activity.',button(buttonLabels[kind]||'Create','orange',`data-admin-demo="${kind}"`))}${content}`;
  }


  function renderMentorAnalytics(context='overview'){
    const title=context==='learners'?'Learner Trends':context==='assessments'?'Assessment Analytics':context==='engagement'?'Learning Engagement':context==='interventions'?'Intervention Center':'Mentor Analytics';
    const filtered=context==='interventions'?learners.filter(item=>item.progress<70):learners;
    return `${heading(title,'Only assigned learners are analysed. Progress, assessment, engagement and access remain identity-linked and permission-aware.',button('Create intervention','orange','data-action="mentor-create-assignment"'))}
      <section class="analytics-hero mentor-analytics-hero"><div><span class="eyebrow">MENTOR COMMAND CENTER</span><h2>See who needs help, why they need it, and the next safe action.</h2><p>No broad learner visibility. Every signal is scoped to assigned learners and exact resources.</p></div><aside><div class="analytics-ring" style="--value:71"><strong>71%</strong><small>Group readiness</small></div><p><strong>Priority:</strong> 2 learners need a CDP intervention this week.</p></aside></section>
      <div class="analytics-kpi-grid">${kpi('Assigned learners',learners.length,'Mentor-scoped')}${kpi('Need attention','2','Low progress or inactivity')}${kpi('Open doubts','3','Resource-linked')}${kpi('Live attendance','82%','Last 4 sessions')}${kpi('Assignments due','4','Next 7 days')}${kpi('Access risks','2','Expiring or missing')}</div>
      <div class="analytics-layout">
        <section class="analytics-card span-2"><header><div><span class="eyebrow">LEARNER HEALTH</span><h2>Progress and intervention priority</h2></div></header>${filtered.map((learner,index)=>analyticsBar(learner.name,learner.progress,`${learner.plan} • ${learner.lastActive}`,index===0?'orange':index===1?'blue':'green')).join('')}</section>
        <section class="analytics-card"><header><div><span class="eyebrow">ASSESSMENTS</span><h2>Accuracy distribution</h2></div></header>${analyticsTrend([52,64,71,78,84],['<50','50–60','60–70','70–80','80+'])}<p class="analytics-note">Group average: <strong>69%</strong>. CDP is the shared weak subject.</p></section>
        <section class="analytics-card"><header><div><span class="eyebrow">ENGAGEMENT</span><h2>Learning actions</h2></div></header><div class="weekly-report-grid"><span><strong>18</strong><small>notes opened</small></span><span><strong>11</strong><small>videos resumed</small></span><span><strong>9</strong><small>tests attempted</small></span><span><strong>6</strong><small>doubts raised</small></span></div></section>
        <section class="analytics-card span-2"><header><div><span class="eyebrow">INTERVENTION QUEUE</span><h2>Actionable learner signals</h2></div></header><div class="analytics-table">${learners.slice(0,4).map((learner,index)=>`<article><span class="learner-dot">${escapeHtml(learner.name.split(' ').map(x=>x[0]).join('').slice(0,2))}</span><div><strong>${escapeHtml(learner.name)}</strong><small>${index===0?'Low CDP accuracy • inactive 3 days':index===1?'Two missed assignments':index===2?'Access expires soon':'On track'}</small></div><span class="state-badge ${index<2?'partial':'open'}">${index<2?'INTERVENE':'ON TRACK'}</span><button data-action="mentor-create-assignment" data-id="${learner.id}">Assign</button></article>`).join('')}</div></section>
      </div>`;
  }

