  function mentorLearnerCard(learner) {
    const initialsValue=learner.name.split(' ').map(item=>item[0]).join('').slice(0,2);
    const weak=learner.id==='learner-rakesh'?'CDP classroom application':learner.id==='learner-rahul'?'Growth & Development accuracy':learner.id==='learner-meera'?'Access continuity':'Timed practice speed';
    return `<article class="mentor-learner-card"><header><span class="mentor-avatar-small">${escapeHtml(initialsValue)}</span><div><h3>${escapeHtml(learner.name)}</h3><p>${escapeHtml(learner.email)}</p></div>${statusPill(learner.status)}</header><div class="mentor-card-meta"><span><strong>${escapeHtml(learner.plan)}</strong><small>Plan</small></span><span><strong>${learner.progress}%</strong><small>Progress</small></span><span><strong>${learner.accessCount}</strong><small>Access</small></span></div><div class="mentor-progress"><i style="width:${learner.progress}%"></i></div><p class="mentor-signal"><strong>Focus:</strong> ${escapeHtml(weak)}<br><strong>Last active:</strong> ${escapeHtml(learner.lastActive)}</p><footer>${button('Open learner','primary',`data-action="mentor-open-learner" data-id="${learner.id}"`)}${button('Assign','secondary',`data-action="mentor-create-assignment" data-id="${learner.id}"`)}</footer></article>`;
  }

  function openMentorLearner(learnerId) {
    const learner=learnerById(learnerId);if(!learner)return;
    const learnerAssignments=state.mentorAssignments.filter(item=>item.learnerId===learnerId);
    const learnerQuestions=state.mentorQuestions.filter(item=>item.learnerId===learnerId);
    const weak=learner.id==='learner-rakesh'?'CDP classroom application':learner.id==='learner-rahul'?'Growth & Development accuracy':learner.id==='learner-meera'?'Access continuity':'Timed practice speed';
    openModal(learner.name,'Assigned learner command center with progress, assessment, engagement, access and intervention context.',`<div class="mentor-modal-kpis">${kpi('Progress',`${learner.progress}%`,'Current completion')}${kpi('Assignments',learnerAssignments.length,'Active and historical')}${kpi('Open questions',learnerQuestions.filter(item=>item.status==='Open').length,'Resource-linked')}${kpi('Exact access',learner.accessCount,learner.status)}</div><div class="mentor-detail-grid"><section class="mentor-detail-panel"><span class="eyebrow">LEARNING SIGNAL</span><h3>${escapeHtml(weak)}</h3><p>Recommended next action is derived from visible progress and assigned work. Production will use real assessment and activity aggregates.</p><div class="mentor-progress large"><i style="width:${learner.progress}%"></i></div></section><section class="mentor-detail-panel"><span class="eyebrow">RECENT WORK</span>${learnerAssignments.map(item=>`<article><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.due)} • ${escapeHtml(item.status)}</small></article>`).join('')||'<p>No assignment yet.</p>'}</section><section class="mentor-detail-panel"><span class="eyebrow">ACCESS</span><p>${escapeHtml(learner.plan)} • ${learner.accessCount} active mapped items</p><p>${/expir/i.test(learner.status)?'Renewal discussion needed.':'No current access alert.'}</p></section><section class="mentor-detail-panel"><span class="eyebrow">QUESTIONS</span>${learnerQuestions.map(item=>`<article><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.status)} • ${escapeHtml(item.createdAt)}</small></article>`).join('')||'<p>No question yet.</p>'}</section></div>`,`${button('Close','secondary','data-action="close-modal"')}${button('Request access','secondary',`data-action="mentor-request-access" data-id="${learner.id}"`)}${button('Create assignment','primary',`data-action="mentor-create-assignment" data-id="${learner.id}"`)}`);
  }

  function openMentorAssignmentForm(learnerId='',resourceId='') {
    const learnerOptions=learners.map(item=>`<option value="${item.id}" ${item.id===learnerId?'selected':''}>${escapeHtml(item.name)} • ${escapeHtml(item.plan)}</option>`).join('');
    const resourceOptions=resources.filter(item=>item.status==='Published').map(item=>`<option value="${item.id}" ${item.id===resourceId?'selected':''}>${escapeHtml(item.title)} • ${escapeHtml(item.requiredPlan)}</option>`).join('');
    openModal('Create learner assignment','Choose an exact learner and exact resource. Assignment never silently grants access.',`<form id="mentorAssignmentForm" class="admin-form-grid"><label class="admin-form-field"><span>Learner</span><select name="learnerId" required>${learnerOptions}</select></label><label class="admin-form-field"><span>Exact resource</span><select name="resourceId" required>${resourceOptions}</select></label><label class="admin-form-field"><span>Assignment title</span><input name="title" required minlength="4" value="Revision assignment"></label><label class="admin-form-field"><span>Due date</span><input name="due" type="datetime-local" required></label><label class="admin-form-field full"><span>Objective</span><textarea name="objective" required minlength="8" placeholder="State the exact learning outcome"></textarea></label><section class="mentor-access-check full"><strong>Access-aware operation</strong><p>The production adapter verifies exact entitlement before creating the real assignment. Missing access creates a separate Admin request.</p></section></form>`,`${button('Cancel','secondary','data-action="close-modal"')}${button('Create assignment','primary','data-action="mentor-save-assignment"')}`);
  }

  function openMentorAssignmentDetail(assignmentId) {
    const item=state.mentorAssignments.find(entry=>entry.id===assignmentId);if(!item)return;
    const learner=learnerById(item.learnerId);const resource=resourceById(item.resourceId);
    openModal(item.title,'Exact-resource assignment detail and review boundary.',`<div class="mentor-detail-grid"><section class="mentor-detail-panel"><span class="eyebrow">LEARNER</span><h3>${escapeHtml(learner?.name||item.learnerId)}</h3><p>${escapeHtml(learner?.plan||'')} • ${escapeHtml(learner?.lastActive||'')}</p></section><section class="mentor-detail-panel"><span class="eyebrow">RESOURCE</span><h3>${escapeHtml(resource?.title||item.resourceId)}</h3><p>${escapeHtml(resource?.requiredPlan||'')} • ${escapeHtml(item.access)}</p></section><section class="mentor-detail-panel full"><span class="eyebrow">OBJECTIVE</span><p>${escapeHtml(item.objective||'Complete the assigned learning action.')}</p></section><section class="mentor-detail-panel"><span class="eyebrow">DUE</span><h3>${escapeHtml(item.due)}</h3></section><section class="mentor-detail-panel"><span class="eyebrow">STATUS</span>${statusPill(item.status)}</section></div>`,`${button('Close','secondary','data-action="close-modal"')}${item.status==='Ready for review'?button('Mark reviewed','primary',`data-action="mentor-review-assignment" data-id="${item.id}"`):button('Open learner','primary',`data-action="mentor-open-learner" data-id="${item.learnerId}"`)}`);
  }

  function mentorAssignmentCard(item) {
    const learner=learnerById(item.learnerId);const resource=resourceById(item.resourceId);
    return `<article class="mentor-operation-card"><header><span class="mentor-op-icon">☑</span><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(learner?.name||item.learnerId)}</p></div>${statusPill(item.status)}</header><p>${escapeHtml(item.objective||'Complete the assigned learning action.')}</p><div class="mentor-op-meta"><span>${escapeHtml(resource?.title||item.resourceId)}</span><span>${escapeHtml(item.due)}</span><span>${escapeHtml(item.access)}</span></div><footer>${button('Details','secondary',`data-action="mentor-open-assignment" data-id="${item.id}"`)}${button('Open learner','primary',`data-action="mentor-open-learner" data-id="${item.learnerId}"`)}</footer></article>`;
  }

  function openMentorQuestion(questionId) {
    const item=state.mentorQuestions.find(entry=>entry.id===questionId);if(!item)return;
    const learner=learnerById(item.learnerId);const resource=resourceById(item.resourceId);
    openModal(item.title,'Answer with exact learner and resource context preserved.',`<div class="mentor-question-context"><span><strong>Learner</strong>${escapeHtml(learner?.name||item.learnerId)}</span><span><strong>Resource</strong>${escapeHtml(resource?.title||item.resourceId)}</span><span><strong>Received</strong>${escapeHtml(item.createdAt)}</span></div><section class="mentor-question-copy"><strong>Question</strong><p>${escapeHtml(item.question)}</p></section>${item.status==='Answered'?`<section class="mentor-answer-copy"><strong>Mentor answer</strong><p>${escapeHtml(item.answer)}</p></section>`:`<form id="mentorAnswerForm"><textarea name="answer" required minlength="8" placeholder="Write clear, resource-aware guidance"></textarea></form>`}`,`${button('Close','secondary','data-action="close-modal"')}${item.status==='Open'?button('Save answer','primary',`data-action="mentor-save-answer" data-id="${item.id}"`):button('Open learner','primary',`data-action="mentor-open-learner" data-id="${item.learnerId}"`)}`);
  }

  function mentorQuestionCard(item) {
    const learner=learnerById(item.learnerId);const resource=resourceById(item.resourceId);
    return `<article class="mentor-operation-card question"><header><span class="mentor-op-icon">?</span><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(learner?.name||item.learnerId)} • ${escapeHtml(item.createdAt)}</p></div>${statusPill(item.status)}</header><p>${escapeHtml(item.question)}</p><div class="mentor-op-meta"><span>${escapeHtml(resource?.title||item.resourceId)}</span></div><footer>${button(item.status==='Open'?'Answer':'Open guidance','primary',`data-action="mentor-open-question" data-id="${item.id}"`)}</footer></article>`;
  }

  function openMentorSessionForm() {
    openModal('Schedule mentor session','Create a session record with a clear learner group, join boundary and attendance workflow.',`<form id="mentorSessionForm" class="admin-form-grid"><label class="admin-form-field"><span>Session title</span><input name="title" required minlength="4" value="CDP Revision Session"></label><label class="admin-form-field"><span>Learner group</span><select name="group"><option>All assigned learners</option><option>Assigned CDP learners</option><option>Premium learners</option><option>Mentorship learners</option></select></label><label class="admin-form-field"><span>Start</span><input name="when" type="datetime-local" required></label><label class="admin-form-field"><span>Session type</span><select name="type"><option>Live Class</option><option>Doubt Session</option><option>Revision Clinic</option></select></label><label class="admin-form-field full"><span>Join URL</span><input name="joinUrl" type="url" placeholder="https://..."></label><section class="mentor-access-check full"><strong>Attendance and access</strong><p>Production verifies learner identity and session entitlement at join time.</p></section></form>`,`${button('Cancel','secondary','data-action="close-modal"')}${button('Schedule session','primary','data-action="mentor-save-session"')}`);
  }

  function openMentorSession(sessionId) {
    const item=state.mentorSessions.find(entry=>entry.id===sessionId);if(!item)return;
    openModal(item.title,'Session detail, learner group, attendance and replay context.',`<div class="mentor-modal-kpis">${kpi('Status',item.status,item.when)}${kpi('Attendance',item.attendance,item.group)}${kpi('Join','Protected','Identity + entitlement')}${kpi('Replay',item.replayUrl?'Ready':'Pending','Published after session')}</div><section class="mentor-detail-panel"><span class="eyebrow">SESSION BOUNDARY</span><p>Join and replay URLs are resolved only after session access verification. This standalone package never exposes a protected permanent URL.</p></section>`,`${button('Close','secondary','data-action="close-modal"')}${item.status==='Replay'?button('Open replay','primary',`data-action="mentor-open-replay" data-id="${item.id}"`):button('Run readiness','primary','data-action="live-readiness"')}`);
  }

  function openStudentAccessRequest(resourceId='') {
    const selected=resourceById(resourceId)||resourceById(state.selectedResourceId)||resources.find(item=>item.accessState==='locked')||resources[0];
    const existing=state.studentAccessRequests.find(item=>item.learnerId===currentLearnerId() && item.resourceId===selected.id && item.scope==='ITEM' && isOpenRequestStatus(item.status));
    if(existing){
      openModal('Access request already open','Duplicate open requests are blocked for the same learner, resource and scope.',accessRequestCard(existing,false),`${button('Close','secondary','data-action="close-modal"')}${button('Open request history','primary','data-go="home/access-requests"')}`);
      return;
    }
    openModal('Request exact access','The request does not grant access. Admin will review the exact resource and requested scope.',`<form id="studentAccessRequestForm" class="admin-form-grid">
      <label class="admin-form-field"><span>Exact resource</span><select name="resourceId">${resources.map(resource=>`<option value="${resource.id}" ${resource.id===selected.id?'selected':''}>${escapeHtml(resource.title)}</option>`).join('')}</select></label>
      <label class="admin-form-field"><span>Requested scope</span><select name="scope"><option>ITEM</option><option>MODULE</option><option>BUNDLE</option><option>PLAN</option></select><small>Admin may narrow or modify scope before grant.</small></label>
      <label class="admin-form-field"><span>Target exam</span><input name="targetExam" value="${escapeHtml(state.studentProfile.targetExam||'CTET Paper II')}"></label>
      <label class="admin-form-field full"><span>Reason</span><textarea name="reason" required minlength="12" placeholder="Why do you need this exact access?"></textarea></label>
      <label class="admin-form-field full"><span>Optional message</span><textarea name="message" placeholder="Additional context for Admin"></textarea></label>
      <div class="continuity-note full"><strong>Request is not access</strong><p>Only the Admin Access Engine can create, extend, restore or revoke an entitlement.</p></div>
    </form>`,`${button('Cancel','secondary','data-action="close-modal"')}${button('Submit request','primary','data-action="submit-student-access-request"')}`);
  }

  function locateAccessRequest(id) {
    const studentIndex=state.studentAccessRequests.findIndex(item=>item.id===id);
    if(studentIndex>=0)return {kind:'student',item:state.studentAccessRequests[studentIndex],index:studentIndex};
    const mentorIndex=state.mentorAccessRequests.findIndex(item=>item.id===id);
    if(mentorIndex>=0)return {kind:'mentor',item:state.mentorAccessRequests[mentorIndex],index:mentorIndex};
    return null;
  }

  function normalizeLocatedRequest(located) {
    return located?.kind==='mentor'?normalizeMentorAccessRequest(located.item):located?.item;
  }

  function updateLocatedRequest(located,updates) {
    if(!located)return;
    if(located.kind==='student')state.studentAccessRequests[located.index]={...state.studentAccessRequests[located.index],...updates};
    else {
      const reverseStatus={submitted:'Pending Admin review',under_review:'Pending Admin review',needs_information:'Discussion needed',approved:'Approved',rejected:'Closed',cancelled:'Closed',expired:'Closed'};
      state.mentorAccessRequests[located.index]={...state.mentorAccessRequests[located.index],...updates,status:reverseStatus[updates.status]||updates.status||state.mentorAccessRequests[located.index].status};
    }
  }

  function openAdminAccessRequestReview(id) {
    const located=locateAccessRequest(id);
    const item=normalizeLocatedRequest(located);
    if(!item)return;
    const resource=resourceById(item.resourceId);
    const learner=learnerById(item.learnerId);
    const duplicate=findDuplicateGrant(item.learnerId,item.scope,item.target||item.resourceId);
    openModal('Review access request','Admin may approve exact scope, modify scope, ask for information, reject or expire.',`<section class="admin-resource-preview access-review-preview">
      <span class="eyebrow">${escapeHtml((item.requesterType||located.kind).toUpperCase())} REQUEST</span>
      <h2>${escapeHtml(resource?.title||item.target)}</h2>
      <div class="admin-preview-facts"><div><small>Learner</small><strong>${escapeHtml(learner?.name||item.learnerEmail||item.learnerId)}</strong></div><div><small>Email</small><strong>${escapeHtml(learner?.email||item.learnerEmail||'')}</strong></div><div><small>Requested scope</small><strong>${escapeHtml(item.scope)}</strong></div><div><small>Exact target</small><strong>${escapeHtml(item.target||item.resourceId)}</strong></div></div>
      <div class="continuity-note"><strong>Reason</strong><p>${escapeHtml(item.reason||'No reason provided.')}</p></div>
      <div class="continuity-note ${duplicate?'warning':''}"><strong>Duplicate grant preview</strong><p>${duplicate?`Active grant already exists: ${escapeHtml(duplicate.id)}.`:'No active duplicate grant found.'}</p></div>
      <form id="adminAccessDecisionForm" class="admin-form-grid">
        <input type="hidden" name="requestId" value="${escapeHtml(item.id)}">
        <label class="admin-form-field"><span>Grant scope</span><select name="scope">${['ITEM','MODULE','BUNDLE','PLAN'].map(scope=>`<option ${scope===item.scope?'selected':''}>${scope}</option>`).join('')}</select></label>
        <label class="admin-form-field"><span>Target</span><input name="target" value="${escapeHtml(item.target||item.resourceId)}" required></label>
        <label class="admin-form-field"><span>Valid until</span><input name="until" type="date"></label>
        <label class="admin-form-field full"><span>Admin note</span><textarea name="adminNote" required minlength="8">Access reviewed against the exact learner and resource context.</textarea></label>
      </form>
    </section>`,`${button('Needs info','secondary',`data-action="admin-access-needs-info" data-id="${item.id}"`)}${button('Reject','secondary',`data-action="admin-access-reject" data-id="${item.id}"`)}${button('Expire','secondary',`data-action="admin-access-expire" data-id="${item.id}"`)}${button('Approve exact access','primary',`data-action="admin-access-approve" data-id="${item.id}"`)}`);
  }

