      ...state.mentorAssignments.filter(item=>['Ready for review','Access needed'].includes(item.status)).map(item=>({type:item.status==='Ready for review'?'REVIEW':'ACCESS',title:item.title,copy:`${learnerById(item.learnerId)?.name||item.learnerId} • ${item.status}`,action:'mentor-open-assignment',id:item.id})),
