      const list=context==='replays'?state.mentorSessions.filter(item=>item.status==='Replay'):state.mentorSessions.filter(item=>item.status==='Scheduled');
      els.page.innerHTML=`${heading(context==='replays'?'Live replays':'Upcoming live sessions','Schedule, prepare, join and review mentor sessions through the same Drive workspace.',button('Schedule session','orange','data-action="mentor-schedule-session"'))}${collectionToolbar(`${list.length} session${list.length===1?'':'s'} in this view`)}<div class="mentor-operation-grid">${list.map(item=>`<article class="mentor-operation-card live"><header><span class="mentor-op-icon">${item.status==='Replay'?'↺':'●'}</span><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.group)}</p></div>${statusPill(item.status)}</header><p>${escapeHtml(item.when)}</p><div class="mentor-op-meta"><span>Attendance ${escapeHtml(item.attendance)}</span><span>${item.status==='Replay'?'Replay protected':'Join protected'}</span></div><footer>${button(item.status==='Replay'?'Open replay detail':'Prepare session','primary',`data-action="mentor-open-session" data-id="${item.id}"`)}</footer></article>`).join('')||emptyState('No session in this view.')}</div>`;
