  function adminOperationalCounts() {
    return {
      content:state.adminResources.length,
      access:state.adminGrants.filter(item=>item.status==='Active'||item.status==='Expiring').length+allAccessRequests().filter(item=>isOpenRequestStatus(item.status)).length,
      people:learners.length+state.adminMentors.length,
      commerce:(commerceReadiness().green?0:1)+state.adminPayments.filter(item=>item.status!=='Approved').length+state.adminRefunds.filter(item=>item.status==='Pending review').length,
      experience:experienceEvents.filter(item=>item.status!=='archived').length+experienceCampaigns.filter(item=>item.status==='Active').length,
      reports:3,
      settings:4
    };
  }

  function adminModuleLabel(type) {
    return ({note:'Notes',video:'Videos',test:'Mock Tests','current-affairs':'Current Affairs',roadmap:'Roadmaps',live:'Live Class',replay:'Replay',resource:'Resource'})[type]||String(type||'Resource');
  }

  function adminResourceKind(record) {
    return ({note:'note',video:'video',test:'mock-test','current-affairs':'current-affairs',roadmap:'roadmap',live:'live-replay',replay:'live-replay'})[record?.type]||'resource';
  }

  function adminActions(buttons) {
    return `<div class="admin-row-actions">${buttons.join('')}</div>`;
  }

  function adminEntityButton(label,entity,operation,id,kind='secondary') {
    return `<button class="v8-${kind}" data-admin-entity-action="${entity}:${operation}" data-id="${escapeHtml(id)}">${escapeHtml(label)}</button>`;
  }

  function renderAdminAuditTable(limit=100) {
    return adminTable(['Time','Actor','Action','Entity','Detail','Status','Trace'],state.adminAudit.slice(0,limit).map(item=>`<tr><td>${escapeHtml(item.time)}</td><td>${escapeHtml(item.actor)}</td><td><code>${escapeHtml(item.action)}</code></td><td>${escapeHtml(item.entity)}</td><td>${escapeHtml(item.detail)}</td><td>${statusPill(item.status)}</td><td>${button('Open','secondary',`data-action="open-access-audit-detail" data-id="${item.id}"`)}</td></tr>`));
  }

  function renderAdminResourceTable(list) {
    return adminTable(['Resource','Module','Access','Status','Updated','Operations'],list.map(record=>`<tr>
      <td><strong>${escapeHtml(record.title)}</strong><small>${escapeHtml(record.id)}</small></td>
      <td>${escapeHtml(adminModuleLabel(record.type))}</td>
      <td>${escapeHtml(record.access||'FREE')}</td>
      <td>${statusPill(record.status||'Draft')}</td>
      <td>${escapeHtml(record.updated||'Not recorded')}</td>
      <td>${adminActions([
        adminEntityButton('Preview','resource','preview',record.id),
        adminEntityButton('Edit','resource','edit',record.id),
        record.status==='Published'?adminEntityButton('Unpublish','resource','unpublish',record.id):adminEntityButton('Publish','resource','publish',record.id,'primary'),
        adminEntityButton('Archive','resource','archive',record.id)
      ])}</td>
    </tr>`));
  }

