  function renderStudent() {
    const parent = state.studentParent;
    const context = state.studentContext;
    if (parent === 'home') return renderStudentHome(context);
    if (parent === 'learning') return renderStudentLearning(context);
    if (parent === 'mentor') return renderMentor(context);
    if (parent === 'live') return renderLive(context);
    if (parent === 'success') return renderSuccess(context);
    return renderHelp(context);
  }


  function renderStudentRedeemAccess() {
    const codeFromHash=(location.hash.match(/[?&](?:key|invite)=([^&]+)/)||[])[1]||'';
    els.page.innerHTML=`${heading('Redeem Access','Use an assigned Access Key or secure email-bound invite. Login and identity validation happen before any entitlement is created.',button('Open My Access','secondary','data-go="home/my-access"'))}
      <section class="access-request-explainer"><div><span class="eyebrow">KEY / INVITE ≠ PASSWORD</span><h2>Redemption creates one normal canonical Access Engine grant.</h2><p>Wrong email, expired, revoked, already-used or exhausted credentials fail closed. A single ITEM key cannot unlock a whole plan.</p></div><aside>${statusPill('Login required')}<small>Every attempt is audit-ready.</small></aside></section>
      <div class="student-redeem-layout">
        <form id="studentRedeemAccessForm" class="student-redeem-card">
          <span class="access-scope-icon">⌁</span><h2>Enter Access Key or Invite Code</h2><p>Use the code sent by AspireNest Admin.</p>
          <label><span>Code</span><input name="code" value="${escapeHtml(decodeURIComponent(codeFromHash||''))}" required placeholder="AN-CDP-7D-AB12"></label>
          <label><span>Registered email</span><input name="email" value="${escapeHtml(state.session.email||state.studentProfile.email||'')}" required type="email"></label>
          ${button('Validate & redeem','orange','data-action="redeem-student-access"')}
        </form>
        <section class="student-redeem-guide"><h2>Safety checks</h2>${[
          ['1','Authenticated account','You must be signed in.'],
          ['2','Email match','Assigned invites and keys match the registered email.'],
          ['3','Validity','Expiry, usage and revocation are checked.'],
          ['4','Exact scope','PLAN, MODULE, BUNDLE or ITEM is preserved.'],
          ['5','Canonical grant','Access appears in My Access after authorization refresh.']
        ].map(item=>`<article><span>${item[0]}</span><div><strong>${item[1]}</strong><small>${item[2]}</small></div></article>`).join('')}</section>
      </div>`;
  }

  function renderStudentHome(context) {
    if (context === 'profile') return renderStudentProfile();
    if (context === 'my-access') return renderMyAccess();
    if (context === 'access-requests') return renderStudentAccessRequests();
    if (context === 'redeem-access') return renderStudentRedeemAccess();
    if (context === 'recent') return renderResourceCollection('Recent learning', resources.filter(resource => resource.recent));
    if (context === 'recommended') return renderResourceCollection('Recommended for you', resources.filter(resource => ['cdp','maths'].includes(resource.subject)).slice(0,6));
    if (context === 'continue') return openExactResource(resourceById('note-child-development'));
    if (context === 'today') {
      els.page.innerHTML = `${heading('Today’s Learning','Complete one assigned test, one note checkpoint and one roadmap day.')}
        <div class="dashboard-grid">${infoCard('Priority 1','Continue CHILD DEVELOPMENT from the exact reading position.')}${infoCard('Priority 2','Attempt CDP Growth & Development chapter test.')}${infoCard('Priority 3','Complete the next AspirePath roadmap day.')}</div>`;
      return;
    }

    const recent = resources.filter(resource => resource.recent).slice(0,6);
    els.page.innerHTML = `${heading(`Welcome back, ${escapeHtml(state.session.displayName || 'Rakesh')}`,'Resume the exact resource, see today’s work and reach everything you can access without choosing a plan first.',`${button('Browse Learning','secondary','data-go="learning/library"')}${button('Open My Access','primary','data-go="home/my-access"')}`)}
      <section class="hero-grid">
        <article class="continue-card"><div class="continue-copy"><span class="eyebrow">CONTINUE LEARNING</span><h2>CHILD DEVELOPMENT</h2><p>Resume the approved IntelliText reader with exact resource identity and saved progress.</p><div class="progress-line"><span style="width:${state.noteProgress}%"></span></div><div class="continue-meta"><span>N Native Note</span><span>CDP</span><span>${state.noteProgress}% complete</span><span>6 min left</span></div><div class="continue-actions">${button('Continue Reading','primary','data-open="note-child-development"')}${button('Add to Revision','secondary','data-action="revision" data-id="note-child-development"')}</div></div><div class="book-visual"><div class="book-cover"><small>ASPIRENEST INTELLITEXT</small><strong>Child Development</strong><span>Premium Learning Note</span></div></div></article>
        <div class="info-stack"><article class="info-card"><h3>Today’s learning</h3><p>Complete one mentor assignment and revise one weak concept.</p><div class="metric">2 <small>priority tasks</small></div></article><article class="info-card"><h3>Upcoming</h3><div class="upcoming-list"><div><span>24</span><strong>Learning Theories Live Revision<small>Tomorrow • 7:00 PM</small></strong></div><div><span>26</span><strong>CDP Chapter Test<small>Sunday • 10:00 AM</small></strong></div></div></article></div>
      </section>
      ${renderStudentMomentum()}
      ${renderStudentExperienceFeed()}
      <section class="section"><div class="section-header"><div><h2>Suggested subjects</h2><p>Open a subject workspace containing learn, practice, revision and roadmap.</p></div></div><div class="subject-grid">${subjects.slice(0,5).map(subjectCard).join('')}</div></section>
      <section class="section"><div class="section-header"><div><h2>Suggested resources</h2><p>Assigned, recent and recommended items — access checked consistently.</p></div><button class="text-button" data-go="learning/library">View all</button></div><div class="resource-grid">${recent.map(resourceCard).join('')}</div></section>`;
  }

  function renderStudentLearning(context) {
    if (context === 'my-access') return renderMyAccess();
    if (context === 'subjects') return renderSubjects();

    const typeMap = {
      notes:['note'],
      videos:['video'],
      practice:['test'],
      'current-affairs':['current-affairs'],
      roadmaps:['roadmap']
    };

    let list = [...resources];
    if (typeMap[context]) list = list.filter(resource => typeMap[context].includes(resource.type));
    if (context === 'assigned') list = list.filter(resource => resource.assigned);
    if (context === 'recent') list = list.filter(resource => resource.recent);
    if (context === 'saved') list = list.filter(resource => state.saved.has(resource.id));

    list = applyLearningFilters(list, context);

    const title = context === 'library'
      ? 'All Learning'
      : context === 'practice'
        ? 'Practice'
        : context === 'current-affairs'
          ? 'Current Affairs'
          : context[0].toUpperCase()+context.slice(1);

    const copy = context === 'library'
      ? 'Search and filter the unified library. Plan badges are informational; exact access decides what opens.'
      : 'Open the exact resource through the approved Learning Drive and continue in the updated exact-resource workspace.';

    els.page.innerHTML = `${heading(title,copy,button('Open My Access','primary','data-go="home/my-access"'))}
      ${libraryToolbar({full:context === 'library'})}
      ${list.length ? `<div class="resource-grid">${list.map(resourceCard).join('')}</div>` : emptyState('No resources in this view')}`;
  }

  function renderStudentAccessRequests() {
    const mine=state.studentAccessRequests.filter(item=>item.learnerId===currentLearnerId());
    const open=mine.filter(item=>isOpenRequestStatus(item.status));
    const approved=mine.filter(item=>item.status==='approved');
    const closed=mine.filter(item=>['rejected','cancelled','expired'].includes(item.status));
    els.page.innerHTML=`${heading('Access Requests','Request exact ITEM, MODULE, BUNDLE or PLAN access without losing the selected resource.',button('Request access','orange','data-action="open-student-access-request"'))}
      <section class="access-request-explainer"><div><span class="eyebrow">REQUEST IS NOT ACCESS</span><h2>Admin approval creates a normal Access Engine grant.</h2><p>Duplicate open requests are blocked. Every decision keeps learner, resource, requested scope, reason, grant ID and audit history connected.</p></div><aside>${statusPill('In-app active')}<small>Automatic Gmail remains prepared but disabled.</small></aside></section>
      <div class="analytics-kpi-grid">${kpi('Open',open.length,'Submitted / review / needs info')}${kpi('Approved',approved.length,'Grant-linked history')}${kpi('Closed',closed.length,'Rejected / cancelled / expired')}${kpi('Email provider',state.emailSettings.automaticEmailMode,'In-app notification remains active')}</div>
      <div class="access-request-list">${mine.map(item=>accessRequestCard(item,false)).join('')||`<section class="admin-empty-premium"><span>◉</span><div><h2>No access request yet</h2><p>Open any locked resource and choose Request Access.</p></div></section>`}</div>`;
  }

  function renderMyAccess() {
    const productionMode=adapter.mode==='production';
    if(productionMode&&!state.productionAccess.loaded&&!state.productionAccess.loading){
      els.page.innerHTML=`${heading('My Access','Loading effective access from the authoritative Access Engine.')}<div class="access-empty-state"><strong>Secure loading…</strong></div>`;
      refreshProductionMyAccess();
      return;
    }
    if(productionMode&&state.productionAccess.loading){
      els.page.innerHTML=`${heading('My Access','Loading effective access from the authoritative Access Engine.')}<div class="access-empty-state"><strong>Secure loading…</strong></div>`;
      return;
    }
    if(productionMode&&state.productionAccess.error){
      els.page.innerHTML=`${heading('My Access','Access is unavailable until the verified entitlement read succeeds.',button('Retry','primary','data-action="refresh-my-access"'))}<div class="access-empty-state"><strong>Access unavailable</strong><small>${escapeHtml(state.productionAccess.error)}</small></div>`;
      return;
    }

    let activePlans=[];let specialAccess=[];let assignedNow=[];let expiringOrExpired=[];
    if(productionMode){
      const activeIds=new Set();const specialIds=new Set();const expiredIds=new Set();
      for(const grant of state.productionAccess.grants){
        const effective=productionGrantStatus(grant);const list=productionResourcesForGrant(grant);
        const scope=String(grant.scopeType||'plan').toLowerCase();
        if(effective==='active'){
          const expiry=grant.accessUntil?new Date(grant.accessUntil):null;
          const expiring=expiry&&Number.isFinite(expiry.getTime())&&expiry.getTime()-Date.now()<=14*24*60*60*1000;
          for(const resource of list){
            if(expiring)expiredIds.add(resource.id);
            if(scope==='item'||scope==='bundle')specialIds.add(resource.id);else activeIds.add(resource.id);
          }
        }else if(['expired','blocked','revoked'].includes(effective)){
          for(const resource of list)expiredIds.add(resource.id);
        }
      }
      const allowedIds=new Set([...activeIds,...specialIds]);
      const assignedIds=new Set(resources.filter(resource=>resource.assigned&&allowedIds.has(resource.id)).map(resource=>resource.id));
      assignedNow=[...assignedIds].map(resourceById).filter(Boolean);
      activePlans=[...activeIds].filter(id=>!assignedIds.has(id)).map(resourceById).filter(Boolean);
      specialAccess=[...specialIds].filter(id=>!assignedIds.has(id)).map(resourceById).filter(Boolean);
      expiringOrExpired=[...expiredIds].map(resourceById).filter(Boolean);
    }else{
      const activePlanIds=['test-mega-paper-ii','note-geography-paper-ii','note-algebra-intro','note-women-reform','note-rural-life'];
      activePlans=activePlanIds.map(resourceById).filter(Boolean);
    }

    els.page.innerHTML = `${heading(
      'My Access',
      'Exactly what this account can open — whether access came from a plan, module, bundle or one exact item.',
      `${button('Browse all','secondary','data-go="learning/library"')}${button('Redeem code','secondary','data-go="home/redeem-access"')}${button('My requests','secondary','data-go="home/access-requests"')}${button('Request access','primary','data-action="open-student-access-request"')}`
    )}
      <div class="access-groups">
        ${accessSection('Active plans & modules','Mapped resources currently available',activePlans,'active')}
        ${accessSection('Special access','Exact item or curated bundle grants',specialAccess,'special')}
        ${accessSection('Assigned resources','Mentor or roadmap tasks visible now',assignedNow,'assigned')}
        ${accessSection('Expiring or expired','Renewal and history remain clear',expiringOrExpired,'expired')}
      </div>
      <section class="access-request-inline"><header><div><span class="eyebrow">REQUEST HISTORY</span><h2>Student → Admin access decisions</h2><p>Requests remain separate from grants and payments.</p></div>${button('Open all requests','secondary','data-go="home/access-requests"')}</header><div class="access-request-list compact">${state.studentAccessRequests.filter(item=>item.learnerId===currentLearnerId()||item.learnerEmail===state.session.email).slice(0,2).map(item=>accessRequestCard(item,false)).join('')}</div></section>`;
  }

  function accessSection(title, subtitle, list, kind='active') {
    const cards=list.map(resource => `<button class="access-resource-card" data-open="${resource.id}">
      <span class="access-resource-icon">${kind==='active'?'✓':typeIcon[resource.type]}</span>
      <span class="access-resource-copy">
        <strong>${escapeHtml(resource.title)}</strong>
        <small>${escapeHtml(resource.requiredPlan.charAt(0)+resource.requiredPlan.slice(1).toLowerCase())} • ${escapeHtml(resource.duration)}</small>
        <em>${kind==='active'?'Active access':kind==='special'?'Special access':kind==='assigned'?'Assigned now':'Renewal required'}</em>
      </span>
    </button>`).join('');

    return `<section class="access-section access-section-${kind}">
      <header class="access-section-header">
        <div><h2>${escapeHtml(title)}</h2><p>${escapeHtml(subtitle)}</p></div>
        <span>${list.length} item${list.length===1?'':'s'}</span>
      </header>
      ${cards?`<div class="access-resource-grid">${cards}</div>`:`<div class="access-empty-state"><strong>No items in this group.</strong></div>`}
    </section>`;
  }

  function subjectCatalog(subject){
    const list=resources.filter(resource=>resource.subject===subject.id);
    const open=list.filter(resource=>['open','partial'].includes(resource.accessState));
    const progress=list.length?Math.round(list.reduce((sum,item)=>sum+Number(item.progress||0),0)/list.length):0;
    return {list,open,progress,assigned:list.filter(resource=>resource.assigned),tests:list.filter(resource=>resource.type==='test'),roadmaps:list.filter(resource=>resource.type==='roadmap'),live:list.filter(resource=>['live','replay'].includes(resource.type))};
  }

  function renderSubjects() {
    const cards=subjects.map(subjectCard).join('');
    const rows=subjects.map(subject=>{
      const catalog=subjectCatalog(subject);
      return `<button class="subject-list-row" data-subject="${subject.id}"><span class="subject-icon" style="background:${subject.tint}">${subject.icon}</span><div><strong>${escapeHtml(subject.name)}</strong><small>${catalog.list.length?`${catalog.list.length} visible resources`:'No published resource in this package'}</small></div><span>${catalog.progress}% progress</span><span>${catalog.open.length} open</span><b>Open →</b></button>`;
    }).join('');
    els.page.innerHTML = `${heading('Subjects','Each subject opens one premium command center for learning, practice, revision, roadmap, live activity, assignments and analytics.')}
      ${collectionToolbar(`${subjects.length} subject workspaces`)}
      <div class="subject-view ${state.view==='list'?'is-list':'is-grid'}">${state.view==='list'?rows:`<div class="subject-grid">${cards}</div>`}</div>`;
  }

  function subjectCard(subject) {
    const catalog=subjectCatalog(subject);
    const copy=catalog.list.length?`${catalog.list.length} visible resources • ${catalog.progress}% progress`:'No published resources • 0% progress';
    return `<button class="subject-card premium" data-subject="${subject.id}" style="--subject-tint:${subject.tint};--subject-accent:${subject.accent}"><span class="subject-icon">${subject.icon}</span><strong>${escapeHtml(subject.name)}</strong><small>${escapeHtml(copy)}</small><span class="subject-card-meta"><i>${catalog.open.length} open</i><i>${catalog.tests.length} practice</i><i>${catalog.assigned.length} assigned</i></span><span class="mini-progress"><i style="width:${catalog.progress}%"></i></span></button>`;
  }

  function subjectEmpty(subject,kind='learning'){
    return `<section class="subject-empty-premium"><span>${subject.icon}</span><div><h2>No published ${escapeHtml(kind)} resource yet</h2><p>${escapeHtml(subject.name)} remains ready for the first canonical resource. Progress stays at 0% until real learner activity exists.</p><div>${button('Browse all learning','secondary','data-go="learning/library"')}${button('Contact support','secondary','data-go="help/contact"')}</div></div></section>`;
  }

  function renderSubjectWorkspace(subjectId) {
    const subject = subjectById(subjectId);
    const catalog=subjectCatalog(subject);
    const list=catalog.list;
    state.selectedSubject = subject.id;
    const primary=list[0]?button('Continue subject','primary',`data-open="${list[0].id}"`):'';
    els.page.innerHTML = `<div class="subject-command-center">${heading(subject.name,'One place for overview, learning, practice, revision, roadmap, live classes, assignments and subject analytics.',`${primary}${button('Check access','secondary','data-go="home/my-access"')}`)}
      <section class="workspace-hero premium-subject-hero"><div><span class="eyebrow">SUBJECT COMMAND CENTER</span><h1>${escapeHtml(subject.name)}</h1><p>${list.length?`${list.length} visible resources with exact access and progress.`:'No published resources are currently available in this package.'}</p><div class="subject-hero-actions">${primary}${button('Open My Access','secondary','data-go="learning/my-access"')}</div></div><div class="workspace-stats"><div class="stat-tile"><strong>${catalog.progress}%</strong><small>Overall progress</small></div><div class="stat-tile"><strong>${list.length}</strong><small>Visible resources</small></div><div class="stat-tile"><strong>${catalog.assigned.length}</strong><small>Assignments</small></div><div class="stat-tile"><strong>${catalog.open.length}</strong><small>Open now</small></div></div></section>
      <div class="workspace-tabs premium-tabs">${[['overview','Overview'],['learn','Learn'],['practice','Practice'],['revision','Revision'],['roadmap','Roadmap'],['live','Live & Replays'],['assignments','Assignments'],['analytics','Analytics']].map(([id,label]) => `<button class="${state.workspaceTab === id ? 'active' : ''}" data-workspace-tab="${id}">${label}</button>`).join('')}</div>
      ${workspaceTabContent(subject,catalog)}</div>`;
  }

  function subjectResourceCollection(list,emptyLabel){
    return `${collectionToolbar(`${list.length} resource${list.length===1?'':'s'}`)}${list.length?`<div class="resource-grid ${state.view==='list'?'list-view':''}">${list.map(resourceCard).join('')}</div>`:emptyLabel}`;
  }

  function workspaceTabContent(subject,catalog) {
    const list=catalog.list;
    if (state.workspaceTab === 'practice') return subjectResourceCollection(catalog.tests,subjectEmpty(subject,'practice'));
    if (state.workspaceTab === 'roadmap') return subjectResourceCollection(catalog.roadmaps,subjectEmpty(subject,'roadmap'));
    if (state.workspaceTab === 'live') return subjectResourceCollection(catalog.live,subjectEmpty(subject,'live or replay'));
    if (state.workspaceTab === 'assignments') return catalog.assigned.length?subjectResourceCollection(catalog.assigned,''):`<div class="subject-dashboard-grid">${infoCard('No active assignment','A Mentor assignment will appear here with exact resource and due date.')}${infoCard('Assignment does not grant access','Missing entitlement creates a separate Admin review request.')}${infoCard('History','Completed assignments remain linked to learner and resource IDs.')}</div>`;
    if (state.workspaceTab === 'revision') return `<div class="subject-dashboard-grid">${infoCard('Revision queue',`${state.revision.size} saved resource${state.revision.size===1?'':'s'}.`)}${infoCard('Highlights & notes',`${state.studyRecords.highlights.length} highlights • ${state.studyRecords.notes.length} personal notes`)}${infoCard('Flashcards',`${state.studyRecords.flashcards.length} recall card${state.studyRecords.flashcards.length===1?'':'s'}`)}${infoCard('Mistake Book',`${state.mock.result?.incorrect||3} questions ready for review`)}</div>`;
    if (state.workspaceTab === 'learn') return subjectResourceCollection(list.filter(resource => ['note','video','current-affairs','replay'].includes(resource.type)),subjectEmpty(subject,'learning'));
    if (state.workspaceTab === 'analytics') {
      if(!list.length)return subjectEmpty(subject,'analytics');
      return `<div class="analytics-layout subject-analytics"><section class="analytics-card span-2"><header><div><span class="eyebrow">SUBJECT TREND</span><h2>${escapeHtml(subject.name)} performance</h2></div></header>${analyticsTrend([42,48,51,60,64,68,catalog.progress],['W1','W2','W3','W4','W5','W6','Now'])}</section><section class="analytics-card"><header><div><span class="eyebrow">STRENGTH</span><h2>Topic map</h2></div></header>${analyticsBar('Concept understanding',Math.max(38,catalog.progress),'Exact resources','blue')}${analyticsBar('Practice accuracy',catalog.tests.length?76:0,catalog.tests.length?'Owned attempts':'No test','orange')}${analyticsBar('Revision consistency',state.revision.size?65:20,'Saved learning','green')}</section><section class="analytics-card"><header><div><span class="eyebrow">NEXT ACTION</span><h2>Recommendation</h2></div></header><p>${list[0]?`Continue ${escapeHtml(list[0].title)}, then review the linked practice or roadmap.`:'Publish the first canonical resource before calculating progress.'}</p></section></div>`;
    }
    if(!list.length)return subjectEmpty(subject);
    return `<div class="subject-overview-grid">
      <section class="subject-overview-card continue"><header><span class="eyebrow">CONTINUE</span><h2>Resume the latest resource</h2></header>${resourceCard(list[0])}</section>
      <section class="subject-overview-card"><header><span class="eyebrow">PRACTICE</span><h2>${catalog.tests.length} published test${catalog.tests.length===1?'':'s'}</h2></header><p>${catalog.tests.length?'Continue an owned attempt or open exact instructions.':'No subject test is published yet.'}</p>${catalog.tests[0]?button('Open practice','primary',`data-open="${catalog.tests[0].id}"`):''}</section>
      <section class="subject-overview-card"><header><span class="eyebrow">REVISION</span><h2>Saved study intelligence</h2></header><p>${state.studyRecords.highlights.length} highlights • ${state.studyRecords.flashcards.length} flashcards • ${state.revision.size} revision items</p><button class="text-button" data-workspace-tab="revision">Open revision →</button></section>
      <section class="subject-overview-card"><header><span class="eyebrow">ROADMAP</span><h2>${catalog.roadmaps.length?'Active subject roadmap':'No roadmap published'}</h2></header><p>Roadmap tasks keep linked Notes, Videos and Tests together.</p>${catalog.roadmaps[0]?button('Open roadmap','secondary',`data-open="${catalog.roadmaps[0].id}"`):''}</section>
      <section class="subject-overview-card"><header><span class="eyebrow">LIVE</span><h2>${catalog.live.length} live / replay item${catalog.live.length===1?'':'s'}</h2></header><p>Upcoming sessions, published replays and attendance context.</p><button class="text-button" data-workspace-tab="live">Open Live & Replays →</button></section>
      <section class="subject-overview-card"><header><span class="eyebrow">ANALYTICS</span><h2>${catalog.progress}% subject progress</h2></header><p>Learning, practice, revision and readiness remain connected.</p><button class="text-button" data-workspace-tab="analytics">Open analytics →</button></section>
    </div>`;
  }

  function renderMentor(context) {
    if (context === 'overview') {
      const p=state.mentorProfessionalProfile;
      els.page.innerHTML = `${heading('Your Academic Mentor','Verified professional identity, guidance, assignments and academic work remain connected to your learner journey.',button('Ask a question','orange','data-go="mentor/ask"'))}${p.visibility?.studentProfile?mentorIdentityHero('student'):emptyState('Assigned mentor profile is not currently visible.')}<div class="dashboard-grid">${infoCard('Active assignments',`${state.mentorAssignments.filter(item=>!['Reviewed','Archived'].includes(item.status)).length} exact-resource tasks`)}${infoCard('Open guidance',`${state.mentorQuestions.filter(item=>item.status==='Open').length} question awaiting response`)}${infoCard('Next live session','Learning Theories Live Revision • Tomorrow • 7:00 PM')}${infoCard('Professional updates',`${mentorVisibleEntries('', 'student').length} academic milestones shared`)}</div>${p.visibility?.showBooks?mentorWorkSections('student'):''}`;
      return;
    }
    if (context === 'assignments') {
      const list=state.mentorAssignments.filter(item=>!['Reviewed','Archived'].includes(item.status));
      els.page.innerHTML=`${heading('Mentor Assignments','Exact resources, objective, due date and access state stay connected.')}<div class="mentor-operation-grid">${list.map(mentorAssignmentCard).join('')||emptyState('No active mentor assignment.')}</div>`;
      return;
    }
    if (context === 'guidance') {
      const answered=state.mentorQuestions.filter(item=>item.status==='Answered');
      els.page.innerHTML=`${heading('Guidance History','Past questions and mentor responses remain attached to the exact learning context.')}<div class="mentor-operation-grid">${answered.map(mentorQuestionCard).join('')||emptyState('No answered mentor guidance yet.')}</div>`;
      return;
    }
    if (context === 'access') {
      els.page.innerHTML=`${heading('Access Discussion','Mentor can explain and request. Admin decides and audits.')}<div class="dashboard-grid">${infoCard('Current plan',state.session.plan)}${infoCard('Requests in discussion',state.mentorAccessRequests.length)}${infoCard('No silent unlock','Assignment never grants commercial access.')}${infoCard('Need help?','Create an exact-resource access request from Help or Mentor.')}</div>`;
      return;
    }
    if (context === 'ask') {
      els.page.innerHTML = `${heading('Ask a Question','Create a resource-specific mentor question without changing access.')}
        <section class="dashboard-card mentor-question"><label>Resource<select id="mentorResource">${resources.map(resource => `<option value="${resource.id}">${escapeHtml(resource.title)}</option>`).join('')}</select></label><label>Question<textarea id="mentorQuestion" placeholder="Write the exact doubt or learning question"></textarea></label>${button('Send question','primary','data-action="submit-mentor-question"')}</section>`;
      return;
    }
    els.page.innerHTML = `${heading('Mentor Guidance','Mentor guidance remains connected to the exact learner and resource.')}${mentorIdentityHero('student')}`;
  }

