  function renderHelp(context) {
    if (context === 'faqs') {
      els.page.innerHTML = `${heading('Frequently Asked Questions','Answers stay connected to the Learning Drive, account and exact-resource access model.',button('Contact support','primary','data-go="help/contact"'))}
        <section class="faq-list">
          <details open><summary>How does exact-resource access work?</summary><p>Every note, video, mock test, roadmap, live class and replay keeps its own resource ID. The Access Engine decides open, partial, locked or expired without changing the selected item.</p></details>
          <details><summary>Will login return me to the same resource?</summary><p>Yes. The selected route is stored as returnTo and restored after a verified sign-in.</p></details>
          <details><summary>Can a mentor grant access?</summary><p>No. A mentor may discuss or request access; only the Admin Access Engine can grant, extend or revoke it.</p></details>
          <details><summary>What happens when access expires?</summary><p>Protected content closes, but title, progress context and renewal guidance remain visible.</p></details>
          <details><summary>Where are Notes highlights and flashcards saved?</summary><p>This standalone package persists them locally. Production wiring saves them against the signed-in learner and exact note.</p></details>
          <details><summary>How are Mock Test attempts protected?</summary><p>Timer, answers, review marks and autosave remain attached to the exact test attempt until submit, result and review.</p></details>
        </section>`;
      return;
    }
    if (context === 'access-help') {
      els.page.innerHTML = `${heading('Access & Plan Help','Understand exactly why a resource opens, locks or requests renewal.',`${button('Review My Access','secondary','data-go="learning/my-access"')}${button('Request exact access','primary','data-action="open-access-request"')}`)}
        <div class="access-help-grid"><article><span class="state-badge open">OPEN</span><h3>Active access</h3><p>Allowed by an active PLAN, MODULE, BUNDLE or exact ITEM grant.</p></article><article><span class="state-badge partial">PARTIAL</span><h3>Preview or limited action</h3><p>Only the allowed sample, section or action is available.</p></article><article><span class="state-badge locked">LOCKED</span><h3>Protected content closed</h3><p>Discovery stays visible; protected assets and actions remain unavailable.</p></article><article><span class="state-badge expired">EXPIRED</span><h3>Renewal required</h3><p>Previous context is preserved while protected content stays closed.</p></article></div>
        <section class="help-process"><h2>Access resolution</h2><div class="journey-grid">${journeyStep('1','Select','Keep the exact resource ID.')}${journeyStep('2','Authorize','Check role, action and entitlement.')}${journeyStep('3','Guide','Open, preview, renew or request help.')}${journeyStep('4','Audit','Record every real access change.')}</div></section>`;
      return;
    }
    if (context === 'contact') {
      els.page.innerHTML = `${heading('Contact AspireNest','Send an account, learning or access request without losing the current context.')}<div class="help-contact-layout"><form id="helpContactForm" class="help-contact-form"><label>Full name<input name="name" required value="${escapeHtml(state.session.displayName||'Rakesh Rana')}"></label><label>Email<input name="email" type="email" required value="${escapeHtml(state.session.email||'')}"></label><label>Topic<select name="topic"><option>Learning resource</option><option>Account & login</option><option>Access & plan</option><option>Mock Test attempt</option><option>Live class</option><option>Other</option></select></label><label>Exact resource ID<input name="resourceId" value="${escapeHtml(state.selectedResourceId||'')}"></label><label class="full">Message<textarea name="message" required minlength="8" placeholder="Describe what happened and what you expected."></textarea></label><div class="full">${button('Prepare support request','primary','data-action="submit-help-contact"')}</div></form><aside class="help-channel-card"><span class="eyebrow">SUPPORT CONTEXT</span><h2>Nothing gets lost</h2><p>The current role, route and exact resource ID are attached to the prepared request.</p><ul><li>Account and verification help</li><li>Resource opening problems</li><li>Access and renewal guidance</li><li>Mock Test and Live support</li></ul></aside></div>`;
      return;
    }
    if (context === 'privacy') {
      els.page.innerHTML = `${heading('Privacy & Learning Data','Understand what the platform stores and what remains protected.')}<div class="dashboard-grid">${infoCard('Account identity','Email, UID, role and verification support secure access decisions.')}${infoCard('Learning progress','Reading, video, roadmap and Mock Test progress stay attached to the learner.')}${infoCard('Study tools','Highlights, notes, doubts, bookmarks and flashcards are private learner records.')}${infoCard('Protected assets','Storage paths and signed delivery never replace authorization.')}${infoCard('Admin audit','Real grants, revokes, publish actions and sensitive changes require audit records.')}${infoCard('Control','Support may help correct account or access data without exposing protected content.')}</div>`;
      return;
    }
    if (context === 'account-help') {
      els.page.innerHTML = `${heading('Account Help','Verification, role and returnTo checks keep the learner in the correct workspace.',button('Open My Access','primary','data-go="learning/my-access"'))}<section class="account-help-panel"><div class="account-help-identity"><span class="avatar">${initials(state.session.displayName||state.session.email)}</span><div><strong>${escapeHtml(state.session.displayName||'AspireNest Student')}</strong><small>${escapeHtml(state.session.email||'No email')} • ${escapeHtml(state.session.plan||'FREE')}</small></div><span class="state-badge open">Verified preview</span></div><div class="account-help-steps"><article><span>1</span><div><h3>Sign in</h3><p>Email/password or Google uses the same verified account identity.</p></div></article><article><span>2</span><div><h3>Verify role</h3><p>Only workspaces allowed for the account are shown.</p></div></article><article><span>3</span><div><h3>Restore returnTo</h3><p>The exact selected resource opens after authentication.</p></div></article><article><span>4</span><div><h3>Resolve access</h3><p>Open, partial, locked or expired guidance is shown clearly.</p></div></article></div></section>`;
      return;
    }
    els.page.innerHTML = `${heading('Help','Get account, learning and access guidance without losing the current resource.',button('Contact support','primary','data-go="help/contact"'))}
      <section class="help-hero"><div><span class="eyebrow">ASPIRENEST SUPPORT</span><h2>Resolve the issue without breaking the learning journey.</h2><p>Resource identity, account role and access context remain attached while support guidance is prepared.</p><div>${button('Report resource problem','primary','data-action="open-support-request"')}${button('Access help','secondary','data-go="help/access-help"')}</div></div><aside><strong>Support status</strong><span class="state-badge open">Available</span><small>Standalone requests are saved locally; production integration sends them to the real support workflow.</small></aside></section>
      <div class="dashboard-grid">${infoCard('Open resource problem','Report the exact note, video, test, roadmap, live class or replay.')}${infoCard('Access request','Prepare an exact ITEM/MODULE/BUNDLE/PLAN request for Admin review.')}${infoCard('Account help','Resolve login, verification, role or returnTo problems.')}${infoCard('Mock Test support','Preserve test ID, attempt state and question context.')}${infoCard('Live support','Check schedule, join window, attendance and replay publication.')}${infoCard('Privacy','Understand identity, progress, study records and audit boundaries.')}</div>`;
  }

  function renderResourceCollection(title,list) {
    els.page.innerHTML = `${heading(title,'Exact resources continue through one Drive-style workspace.')}<div class="resource-grid">${list.map(resourceCard).join('')}</div>`;
  }

  function renderSearchResults() {
    const query = state.query.toLowerCase().trim();
    const list = resources.filter(resource => `${resource.title} ${resource.subtitle} ${resource.chapter} ${resource.requiredPlan}`.toLowerCase().includes(query));
    els.page.innerHTML = `${heading('Search results',`Results for “${state.query}”.`,button('Clear search','secondary','data-action="clear-search"'))}
      ${collectionToolbar(`${list.length} matching resource${list.length === 1 ? '' : 's'}`)}
      ${list.length ? `<div class="resource-grid">${list.map(resourceCard).join('')}</div>` : emptyState('No matching resources')}`;
  }

  function collectionToolbar(summary) {
    return `<section class="collection-toolbar"><span>${escapeHtml(summary)}</span><div class="view-toggle"><button data-view="list" class="${state.view === 'list' ? 'active' : ''}" aria-label="List view">☷</button><button data-view="grid" class="${state.view === 'grid' ? 'active' : ''}" aria-label="Grid view">▦</button></div></section>`;
  }

  function applyLearningFilters(list, context) {
    let filtered = [...list];

    if (state.accessFilter === 'access') filtered = filtered.filter(resource => ['open','partial'].includes(resource.accessState));
    if (state.accessFilter === 'free') filtered = filtered.filter(resource => resource.requiredPlan === 'FREE');
    if (state.accessFilter === 'assigned') filtered = filtered.filter(resource => resource.assigned);
    if (state.accessFilter === 'saved') filtered = filtered.filter(resource => state.saved.has(resource.id));

    if (context === 'library' && state.typeFilter !== 'all') {
      const typeMap = {
        notes:['note'],
        videos:['video','replay','live'],
        practice:['test'],
        'current-affairs':['current-affairs'],
        roadmaps:['roadmap']
      };
      filtered = filtered.filter(resource => (typeMap[state.typeFilter] || []).includes(resource.type));
    }

    if (context === 'library' && state.subjectFilter !== 'all') {
      filtered = filtered.filter(resource => resource.subject === state.subjectFilter);
    }

    return filtered;
  }

  function filterChip(label, attrs, active=false) {
    return `<button type="button" class="filter-chip ${active ? 'active' : ''}" ${attrs}>${escapeHtml(label)}</button>`;
  }

  function libraryToolbar({full=false}={}) {
    const accessChips = [
      ['all','All Content'],
      ['access','My Access'],
      ['free','Free'],
      ['assigned','Assigned'],
      ['saved','Saved']
    ];
    const typeChips = [
      ['all','All'],
      ['notes','Notes'],
      ['videos','Videos'],
      ['practice','Practice'],
      ['current-affairs','Current Affairs'],
      ['roadmaps','Roadmaps']
    ];

    const accessRow = accessChips.map(([id,label]) =>
      filterChip(label,`data-access-filter="${id}"`,state.accessFilter === id)
    ).join('');

    const typeRow = typeChips.map(([id,label]) =>
      filterChip(label,`data-type-filter="${id}"`,state.typeFilter === id)
    ).join('');

    const subjectRow = [
      filterChip('All Subjects','data-subject-filter="all"',state.subjectFilter === 'all'),
      ...subjects.map(subject => filterChip(subject.short,`data-subject-filter="${subject.id}"`,state.subjectFilter === subject.id))
    ].join('');

    return `<section class="library-toolbar" aria-label="Learning filters">
      <div class="toolbar-top">
        <div class="chip-row" aria-label="Access filters">${accessRow}</div>
        <div class="view-toggle" aria-label="View options"><button data-view="list" class="${state.view === 'list' ? 'active' : ''}" aria-label="List view">☷</button><button data-view="grid" class="${state.view === 'grid' ? 'active' : ''}" aria-label="Grid view">▦</button></div>
      </div>
      ${full ? `<div class="chip-row" aria-label="Content type filters">${typeRow}</div><div class="chip-row" aria-label="Subject filters">${subjectRow}</div>` : ''}
    </section>`;
  }

  function resourceCard(resource) {
    const saved = state.saved.has(resource.id);
    const displayState = resource.accessState === 'partial' ? 'Exact item' : resource.accessState[0].toUpperCase()+resource.accessState.slice(1);
    return `<article class="resource-card" data-resource-card="${resource.id}">
      <div class="resource-thumb" style="--thumb-start:${thumb(resource.type)[0]};--thumb-end:${thumb(resource.type)[1]}"><span class="resource-type-icon">${typeIcon[resource.type] || '▤'}</span><span class="state-badge ${resource.accessState === 'partial' ? 'partial' : resource.accessState}">${escapeHtml(displayState)}</span></div>
      <div class="resource-body"><div class="resource-meta"><small>${escapeHtml(typeLabel[resource.type])} • ${escapeHtml(subjectById(resource.subject).name)}</small><span class="plan-badge">${escapeHtml(resource.requiredPlan)}</span></div><h3 class="resource-title"><button class="resource-title-button" data-open="${resource.id}" aria-label="Open ${escapeHtml(resource.title)}">${highlight(resource.title)}</button></h3><p class="resource-subtitle">${highlight(resource.subtitle)}</p><div class="resource-progress"><span style="width:${resource.progress || 0}%"></span></div></div>
      <div class="resource-footer"><small>${escapeHtml(resource.duration)}</small><div class="card-actions"><button class="card-icon-button ${saved ? 'saved' : ''}" data-action="save" data-id="${resource.id}" aria-label="Save resource">${saved ? '★' : '☆'}</button><button class="card-icon-button resource-more-v23" data-resource-menu-v23="${resource.id}" aria-haspopup="menu" aria-label="More actions for ${escapeHtml(resource.title)}">⋮</button></div></div>
    </article>`;
  }

  function thumb(type) {
    return ({note:['#dce8ff','#fff6e8'],video:['#e7f7f1','#edf6ff'],test:['#fff0e4','#ffe9ef'],'current-affairs':['#fff3dc','#fff8e8'],roadmap:['#ece8ff','#fff0ea'],live:['#e4f4ff','#edf6ff'],replay:['#e4f4ff','#f6efff']})[type] || ['#e7edf5','#f8fafc'];
  }

  function highlight(text) {
    const query = state.query.trim();
    if (!query) return escapeHtml(text);
    const safe = query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    return escapeHtml(text).replace(new RegExp(`(${safe})`,'ig'),'<mark class="search-highlight">$1</mark>');
  }

  function kpi(label,value,detail) {
    return `<article class="kpi-card"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(detail)}</small></article>`;
  }
  function infoCard(title,copy) { return `<article class="dashboard-card"><h3>${escapeHtml(title)}</h3><p>${escapeHtml(copy)}</p></article>`; }
  function journeyStep(number,title,copy) { return `<article class="journey-step"><span>${number}</span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(copy)}</small></article>`; }
  function emptyState(message) { return `<div class="empty-state"><div class="empty-icon">⌕</div><h3>${escapeHtml(message)}</h3><p>Try a different view. Protected resources remain visible with clear access guidance.</p></div>`; }

  function previewResource(resource) {
    state.selectedResourceId = resource.id;
    const labelPair = actionLabel[resource.type] || ['Open this resource','Login to open this resource'];
    const primaryLabel = state.session.authenticated ? labelPair[0] : labelPair[1];
    openModal(
      resource.title,
      'Public preview of the canonical learning resource.',
      `<article class="preview-resource-card"><span class="feature-icon">${typeIcon[resource.type]}</span><h3>${escapeHtml(typeLabel[resource.type])} • ${escapeHtml(subjectById(resource.subject).name)}</h3><p>Delivery: ${escapeHtml(typeLabel[resource.type])}<br>Access: ${escapeHtml(resource.requiredPlan)}<br>Status: ${escapeHtml(resource.status)}<br>Updated: Live record</p><div class="v8-card-meta"><span>${escapeHtml(resource.duration)}</span><span>${escapeHtml(resource.requiredPlan)}</span></div></article><div class="continuity-note"><strong>Same resource continues</strong><p>Login and access verification keep this exact selection. AspireNest will not send you to a generic dashboard or unrelated old screen.</p></div>`,
      `${button('Close','secondary','data-action="close-modal"')}${button(primaryLabel,'primary',`data-action="continue-resource" data-id="${resource.id}"`)}`
    );
  }

  function openModal(title,copy,body,footer='') {
    els.modalRoot.innerHTML = `<section class="modal-backdrop"><div class="app-modal" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><header><div><h2>${escapeHtml(title)}</h2><p>${escapeHtml(copy)}</p></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></header><div class="app-modal-body">${body}</div>${footer ? `<footer>${footer}</footer>` : ''}</div></section>`;
  }

  function closeModal() { els.modalRoot.innerHTML = ''; }

  async function continueResource(resource) {
    const route = exactRoute(resource);
    if (!state.session.authenticated) {
      state.pendingRoute = route;
      storage.setItem(STORAGE.pendingRoute, route);
      showLogin(resource);
      return;
    }
    await authorizeAndOpen(resource, route);
  }

  function showLogin(resource) {
    openModal(
      'Continue with your registered account',
      `The selected ${typeLabel[resource.type]} will open after secure login and exact access verification.`,
      `<div class="login-panel"><span class="feature-icon">${typeIcon[resource.type]}</span><h3>${escapeHtml(resource.title)}</h3><p>Return destination:</p><code>${escapeHtml(exactRoute(resource))}</code><label>Email<input id="loginEmail" type="email" value="rakeshrana8590@gmail.com"></label><div class="continuity-note"><strong>No generic redirect</strong><p>Successful login returns to this exact resource route.</p></div></div>`,
      `${button('Cancel','secondary','data-action="close-modal"')}${button('Continue with demo login','primary',`data-action="demo-login" data-id="${resource.id}"`)}`
    );
  }

  async function performLogin(resourceId) {
    const email = document.getElementById('loginEmail')?.value || 'rakeshrana8590@gmail.com';
    state.session = await adapter.login({ email, displayName:'Rakesh Rana', returnTo:state.pendingRoute });
    closeModal();
    const resource = resourceById(resourceId) || resourceFromExactHash(state.pendingRoute);
    if (resource) await authorizeAndOpen(resource, state.pendingRoute || exactRoute(resource));
  }

  async function authorizeAndOpen(resource, route) {
    const decision = await adapter.authorize({ resource, action:actionFor(resource.type), session:state.session });
    if (decision.state === 'login_required') return showLogin(resource);
    if (decision.state === 'locked') return showLocked(resource);
    if (decision.state === 'expired') return showExpired(resource);
    if (decision.state !== 'allowed') return showError(resource, decision);
    storage.removeItem(STORAGE.pendingRoute);
    state.pendingRoute = '';
    setRole('student');
    history.replaceState(null,'',route);
    renderExactWorkspace(resource);
    adapter.recordProgress?.({resourceId:resource.id,resourceType:resource.type,progress:Number(resource.progress||0),continueState:{route}}).catch?.(error=>lp4OperationFailure('record-recent',error));
  }

  function actionFor(type) {
    return ({note:'READ',video:'WATCH',test:'ATTEMPT','current-affairs':'READ',roadmap:'OPEN',live:'JOIN',replay:'WATCH'})[type] || 'OPEN';
  }

  function exactRoute(resource) {
    return `#student/resource/${encodeURIComponent(resource.type)}/${encodeURIComponent(resource.id)}`;
  }

  function resourceFromExactHash(hash) {
    const parts = String(hash || '').replace(/^#/,'').split('/').filter(Boolean);
    if (parts[0] === 'student' && parts[1] === 'resource' && parts[3]) return resourceById(decodeURIComponent(parts[3]));
    return null;
  }

  function renderExactWorkspace(resource) {
    state.selectedResourceId = resource.id;
    if (!['video','replay'].includes(resource.type)) { stopPlayerClock(); setIntelliPlayerFocus(false); }
    if (resource.type === 'note') return renderNoteWorkspace(resource);
    if (resource.type === 'video' || resource.type === 'replay') return renderVideoWorkspace(resource);
    if (resource.type === 'test') return renderTestInstructions(resource);
    if (resource.type === 'current-affairs') return renderCurrentAffairsWorkspace(resource);
    if (resource.type === 'roadmap') return renderRoadmapWorkspace(resource);
    if (resource.type === 'live') return renderLiveWorkspace(resource);
    return renderUnsupportedWorkspace(resource);
  }

  function exactWorkspaceHeader(resource, eyebrow, actions='') {
    return `<div class="exact-back-row"><button class="text-button" data-action="back-to-library">← Back to Learning</button><span class="state-badge ${resource.accessState === 'partial' ? 'partial' : 'open'}">${resource.accessState === 'partial' ? 'Exact item access' : 'Open'}</span></div>${heading(resource.title,resource.description,actions)}<div class="exact-resource-meta"><span><small>Type</small><strong>${escapeHtml(typeLabel[resource.type])}</strong></span><span><small>Subject</small><strong>${escapeHtml(subjectById(resource.subject).name)}</strong></span><span><small>Duration</small><strong>${escapeHtml(resource.duration)}</strong></span><span><small>Access</small><strong>${escapeHtml(resource.requiredPlan)}</strong></span></div>`;
  }

  function renderReaderWorkspace(resource) {
    ensureReaderContext(resource);
    const mode=state.reader.mode==='study'?'study':'book';
    const label=resource.type==='current-affairs'?'CURRENT AFFAIRS INTELLITEXT / INTELLIBOOK':'INTELLITEXT / INTELLIBOOK';
    const progress=readerProgress(resource);
    els.page.innerHTML = `<div class="exact-workspace note-workspace current-reader-${resource.type} reader-mode-${mode}">${exactWorkspaceHeader(resource,label,`${button('Book View',mode==='book'?'primary':'secondary','data-action="reader-mode" data-mode="book"')}${button('Study View',mode==='study'?'primary':'secondary','data-action="reader-mode" data-mode="study"')}`)}
      <div class="reader-toolbar exact-reader-toolbar"><button data-study-action="highlight">Highlight</button><button data-study-action="underline">Underline</button><button data-study-action="note">Personal Note</button><button data-study-action="doubt">Mark as Doubt</button><button data-study-action="bookmark">Bookmark</button><button data-study-action="flashcard">Create Flashcard</button><button data-study-action="revision">Add to Revision</button></div>
      <div class="reader-progress"><span id="noteProgressBar" style="width:${progress}%"></span></div>
      ${mode==='book'?renderBookView(resource):renderStudyView(resource)}
      <div class="page-actions exact-footer-actions">${button('Mark section complete','secondary','data-action="note-progress"')}${button('Return to Learning Drive','primary','data-action="back-to-library"')}</div>
    </div>`;
    if(mode==='study')queueMicrotask(()=>document.getElementById(`reader-${state.reader.activeSection}`)?.scrollIntoView({block:'start'}));
  }

  function renderNoteWorkspace(resource) { return renderReaderWorkspace(resource); }

  function persistPlayerState(){
    const safe={...state.player,timerId:null};
    storage.setItem(STORAGE.playerState,JSON.stringify(safe));
    storage.setItem(STORAGE.videoProgress,state.videoProgress);
  }

  function persistPlayerRecords(){
    storage.setItem(STORAGE.playerRecords,JSON.stringify(state.playerRecords));
  }

  function updatePlayerProgressUI(){
    const progress=Math.max(0,Math.min(100,Number(state.videoProgress)||0));
    document.getElementById('videoProgressBar')?.style.setProperty('width',`${progress}%`);
    const label=document.getElementById('videoProgressLabel');if(label)label.textContent=`${progress}%`;
    const current=document.getElementById('playerCurrentTime');if(current)current.textContent=`${Math.floor(progress*24/100)}:${String(Math.floor((progress*14)%60)).padStart(2,'0')}`;
  }

  function stopPlayerClock(){
    if(state.player.timerId)clearInterval(state.player.timerId);
    state.player.timerId=null;
  }

  function startPlayerClock(){
    stopPlayerClock();
    if(!state.player.playing)return;
    state.player.timerId=setInterval(()=>{
      state.videoProgress=Math.min(100,state.videoProgress+1);
      updatePlayerProgressUI();
      persistPlayerState();
      adapter.recordProgress({resourceId:state.selectedResourceId,progress:state.videoProgress});
      if(state.videoProgress>=100){state.player.playing=false;stopPlayerClock();renderVideoWorkspace(resourceById(state.selectedResourceId));}
    },1800);
  }

  function setIntelliPlayerFocus(active){
    state.player.focus=Boolean(active);
    document.body.classList.toggle('intelliplayer-focus-mode',state.player.focus);
    els.app.classList.toggle('intelliplayer-focus-mode',state.player.focus);
    persistPlayerState();
  }

  function playerTranscript(resource){
    const rows=[
      ['00:00','Why social learning matters','Learning does not occur in isolation. Vygotsky places language, culture and social interaction at the centre of development.'],
      ['04:15','Zone of Proximal Development','The ZPD describes tasks a learner cannot yet complete independently but can perform with appropriate support.'],
      ['09:40','Scaffolding','Temporary prompts, modelling, questions and feedback are gradually removed as learner independence grows.'],
      ['15:20','More Knowledgeable Other','A teacher, peer, parent or tool may provide the guidance needed for the next level of performance.'],
      ['20:10','Exam checkpoint','Differentiate independent level, potential level and the support that bridges them.']
    ];
    return `<div class="intelliplayer-transcript">${rows.map((row,index)=>`<button class="${state.player.chapter===index?'active':''}" data-action="player-chapter" data-index="${index}" data-progress="${[0,18,40,64,84][index]}"><time>${row[0]}</time><div><strong>${escapeHtml(row[1])}</strong><p>${escapeHtml(row[2])}</p></div></button>`).join('')}</div>`;
  }

  function renderVideoWorkspace(resource) {
    const progress=resource.type==='replay'?Math.max(74,state.videoProgress):state.videoProgress;
    const playing=Boolean(state.player.playing);
    els.page.innerHTML = `<div class="exact-workspace video-workspace intelliplayer-workspace">${exactWorkspaceHeader(resource,'ASPIRENEST INTELLIPLAYER',`${button('Focus mode',state.player.focus?'primary':'secondary','data-action="player-focus"')}${button('Ask Mentor', 'secondary',`data-action="mentor-resource" data-id="${resource.id}"`)}`)}
      <section class="intelliplayer-shell">
        <header class="intelliplayer-topline"><div><span class="state-badge open">PROTECTED STREAM</span><strong>${escapeHtml(resource.title)}</strong></div><div class="intelliplayer-top-actions"><button data-action="player-captions" class="${state.player.captions?'active':''}">CC</button><button data-action="player-quality">${escapeHtml(state.player.quality)}</button><button data-action="player-pip">PiP</button><button data-action="player-fullscreen">Full screen</button></div></header>
        <div class="intelliplayer-stage"><button class="intelliplayer-main-play" data-action="toggle-video" aria-label="${playing?'Pause':'Play'} video">${playing?'Ⅱ':'▶'}</button><div class="intelliplayer-stage-copy"><span class="eyebrow">CHAPTER ${state.player.chapter+1}</span><h2>${['Why Social Learning Matters','Zone of Proximal Development','Scaffolding in Practice','More Knowledgeable Other','Exam Checkpoint'][state.player.chapter]||'Classroom Learning'}</h2><p>${playing?'Playing protected learning stream':'Resume from your saved progress'}</p></div><div class="intelliplayer-corner"><span>${escapeHtml(state.player.quality)}</span><span>${state.player.speed}×</span><span>${state.player.captions?'CC ON':'CC OFF'}</span></div></div>
        <div class="intelliplayer-controls">
          <button class="player-icon" data-action="toggle-video">${playing?'Ⅱ':'▶'}</button>
          <button class="player-icon" data-action="player-seek" data-delta="-5">−5</button>
          <span id="playerCurrentTime">${Math.floor(progress*24/100)}:${String(Math.floor((progress*14)%60)).padStart(2,'0')}</span>
          <div class="video-progress intelliplayer-progress" data-action="player-progress"><span id="videoProgressBar" style="width:${progress}%"></span>${[0,18,40,64,84].map(value=>`<i style="left:${value}%"></i>`).join('')}</div>
          <strong id="videoProgressLabel">${progress}%</strong>
          <button class="player-icon" data-action="player-seek" data-delta="5">+5</button>
          <button data-action="player-volume">🔊 ${state.player.volume}%</button>
          <button data-action="player-speed">${state.player.speed}×</button>
        </div>
      </section>
      <div class="intelliplayer-layout">
        <section class="intelliplayer-main-panel">
          <div class="intelliplayer-tabs"><button class="${state.player.transcript?'active':''}" data-action="player-transcript">Transcript</button><button data-action="player-open-notes">My Notes <span>${state.playerRecords.notes.length}</span></button><button data-action="player-bookmark">Bookmark time <span>${state.playerRecords.bookmarks.length}</span></button><button data-action="player-doubt">Mark doubt <span>${state.playerRecords.doubts.length}</span></button></div>
          ${state.player.transcript?playerTranscript(resource):`<div class="player-notes-empty"><h3>Transcript hidden</h3><p>Open transcript to jump to a chapter and follow the concept text.</p></div>`}
        </section>
        <aside class="intelliplayer-side-panel">
          <section><span class="eyebrow">CLASS INTELLIGENCE</span><h2>Learn, note, question and continue.</h2><div class="player-intelligence-grid"><span><strong>${progress}%</strong><small>watched</small></span><span><strong>${state.playerRecords.notes.length}</strong><small>notes</small></span><span><strong>${state.playerRecords.bookmarks.length}</strong><small>bookmarks</small></span><span><strong>${state.playerRecords.doubts.length}</strong><small>doubts</small></span></div></section>
          <section><h3>Linked learning</h3><button data-open="note-child-development"><span>N</span><div><strong>CHILD DEVELOPMENT</strong><small>Open IntelliBook</small></div></button><button data-open="test-cdp-growth"><span>✓</span><div><strong>CDP Chapter Test</strong><small>Open exact instructions</small></div></button></section>
          <section><h3>Attachments</h3><button data-action="player-attachment"><span>▤</span><div><strong>Class summary</strong><small>PDF • access controlled</small></div></button></section>
        </aside>
      </div>
      <div class="page-actions exact-footer-actions">${button('Previous lesson','secondary','data-action="player-previous"')}${button('Save progress','secondary','data-action="player-save"')}${button('Next: CDP Chapter Test','primary','data-open="test-cdp-growth"')}</div>
    </div>`;
    updatePlayerProgressUI();
    if(playing)startPlayerClock();
  }

  function openPlayerNoteDialog(kind='note'){
    const labels={note:['Add timestamp note','Write a personal class note tied to this exact video progress.'],doubt:['Mark timestamp doubt','Save a question for Mentor guidance with exact video context.']};
    const [title,copy]=labels[kind]||labels.note;
    openModal(title,copy,`<form id="playerRecordForm" class="admin-form-grid"><input type="hidden" name="kind" value="${kind}"><label class="admin-form-field"><span>Timestamp</span><input name="timestamp" value="${state.videoProgress}% watched" readonly></label><label class="admin-form-field"><span>${kind==='doubt'?'Question':'Note'}</span><textarea name="text" required minlength="3" placeholder="${kind==='doubt'?'What needs clarification?':'Write your learning note'}"></textarea></label></form>`,`${button('Cancel','secondary','data-action="close-modal"')}${button(kind==='doubt'?'Save doubt':'Save note','primary','data-action="save-player-record"')}`);
  }

  function setFocusedExamMode(active) {
    document.body.classList.toggle('focused-exam-mode', Boolean(active));
    els.app.classList.toggle('focused-exam-mode', Boolean(active));
  }

  function stopMockClock() {
    if (state.mock.timerId) clearInterval(state.mock.timerId);
    state.mock.timerId = null;
  }

  function formatMockTime(totalSeconds) {
    const safe=Math.max(0,Number(totalSeconds)||0);
    const hours=Math.floor(safe/3600);
    const minutes=Math.floor((safe%3600)/60);
    const seconds=safe%60;
    return `${hours?String(hours).padStart(2,'0')+':':''}${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;
  }

  function mockAnsweredCount() {
    return state.mock.questions.filter(question => state.mock.answers[question.id] !== undefined).length;
  }

  function mockQuestionState(index) {
    const question=state.mock.questions[index];
    const answered=question && state.mock.answers[question.id] !== undefined;
    const review=question && state.mock.flagged.has(question.id);
    const visited=state.mock.visited.has(index);
    if (review && answered) return 'review-answered';
    if (review) return 'review';
    if (answered) return 'answered';
    if (visited) return 'not-answered';
    return 'not-visited';
  }

  function persistMockDraft(action='AUTOSAVE') {
    const resource=resourceById(state.mock.resourceId);
    if(!resource)return;
    const payload={
      resourceId:resource.id,
      action,
      index:state.mock.index,
      answers:state.mock.answers,
      flagged:[...state.mock.flagged],
      visited:[...state.mock.visited],
      remainingSeconds:state.mock.remainingSeconds,
      startedAt:state.mock.startedAt,
      questionCount:state.mock.questions.length
    };
    storage.setItem(STORAGE.mockAttempt,JSON.stringify(payload));
    adapter.recordAttempt(payload).catch?.(()=>{});
  }

  function updateMockClockDom() {
    const timer=document.getElementById('examTimer');
    if(timer)timer.textContent=formatMockTime(state.mock.remainingSeconds);
    const answered=document.getElementById('examAnswered');
    if(answered)answered.textContent=String(mockAnsweredCount());
    const question=document.getElementById('examQuestionNumber');
    if(question)question.textContent=`${state.mock.index+1}/${state.mock.questions.length}`;
  }

  function startMockClock(resource) {
    if(state.mock.timerId)return;
    state.mock.timerId=setInterval(()=>{
      state.mock.remainingSeconds=Math.max(0,state.mock.remainingSeconds-1);
      updateMockClockDom();
      if(state.mock.remainingSeconds%15===0)persistMockDraft('AUTOSAVE');
      if(state.mock.remainingSeconds<=0){
        stopMockClock();
        submitTest(resource,{auto:true});
      }
    },1000);
  }

  async function startMockAttempt(resource) {
    stopMockClock();
    let external=null;
    try { external=await adapter.loadMockTest?.({resourceId:resource.id,canonicalRoute:resource.canonicalRoute}); } catch(_) {}
    state.mock.resourceId=resource.id;
    state.mock.questions=buildMockQuestions(resource,external?.questions || external?.items || []);
    state.mock.index=0;
    state.mock.answers={};
    state.mock.flagged=new Set();
    state.mock.visited=new Set([0]);
    state.mock.submitted=false;
    state.mock.result=null;
    state.mock.paletteRange=0;
    state.mock.textScale=1;
    const durationMinutes=Number(external?.durationMinutes || parseInt(resource.duration,10) || (/mega/i.test(resource.title)?180:30));
    state.mock.durationSeconds=durationMinutes*60;
    state.mock.remainingSeconds=state.mock.durationSeconds;
    state.mock.startedAt=new Date().toISOString();
    state.mock.source=external?.questions?.length?'live-adapter':'package-fallback';
    persistMockDraft('START');
    renderTestAttempt(resource);
  }

  function renderTestInstructions(resource) {
    setFocusedExamMode(false);
    stopMockClock();
    const questionCount=/mega/i.test(resource.title)||resource.id==='test-mega-paper-ii'?200:30;
    const duration=parseInt(resource.duration,10)||(/mega/i.test(resource.title)?180:30);
    state.mock.resourceId=resource.id;
    els.page.innerHTML = `<div class="exact-workspace test-workspace">${exactWorkspaceHeader(resource,'MOCK TEST WORKSPACE')}
      <div class="test-summary"><div><span>Questions</span><strong>${questionCount}</strong></div><div><span>Marks</span><strong>${questionCount}</strong></div><div><span>Duration</span><strong>${duration} min</strong></div><div><span>Access</span><strong>${resource.accessState === 'partial' ? 'This test only' : resource.requiredPlan}</strong></div></div>
      <article class="test-instructions"><span class="eyebrow">BEFORE YOU BEGIN</span><h2>Live Mock Test instructions</h2><p>The exact selected test remains attached across Start, Attempt, Submit, Result and Review. Starting the attempt opens the focused exam workspace inside this same AspireNest app.</p><ul><li>Timer, question palette, answer states and review states are preserved during the attempt.</li><li>Use Clear Response, Mark for Review & Next, or Save & Next exactly as in the live engine.</li><li>A draft is stored locally and the production adapter receives autosave events.</li><li>Submitting opens the result for this same test ID.</li></ul>${button('Start this test','primary',`data-action="start-test" data-id="${resource.id}"`)}</article>
    </div>`;
  }

  function paletteRangeButtons() {
    const total=state.mock.questions.length;
    const ranges=Math.ceil(total/25);
    return Array.from({length:ranges},(_,range)=>{
      const start=range*25+1;
      const end=Math.min(total,start+24);
      return `<button class="exam-range-tab ${range===state.mock.paletteRange?'active':''}" data-palette-range="${range}">${start}-${end}</button>`;
    }).join('');
  }

  function paletteQuestionButtons() {
    const start=state.mock.paletteRange*25;
    return state.mock.questions.slice(start,start+25).map((question,offset)=>{
      const index=start+offset;
      return `<button class="exam-palette-number ${mockQuestionState(index)} ${index===state.mock.index?'current':''}" data-question-index="${index}">${index+1}</button>`;
    }).join('');
  }

  function examStatusLabel(question) {
    const answered=state.mock.answers[question.id]!==undefined;
    const review=state.mock.flagged.has(question.id);
    if(review&&answered)return 'Answered & Marked';
    if(review)return 'Marked for Review';
    return answered?'Answered':'Not Answered';
  }

  function renderTestAttempt(resource) {
    if(!state.mock.questions.length)return startMockAttempt(resource);
    setFocusedExamMode(true);
    state.mock.visited.add(state.mock.index);
    const question=state.mock.questions[state.mock.index];
    const answered=state.mock.answers[question.id];
    const total=state.mock.questions.length;
    const answeredCount=mockAnsweredCount();
    const reviewCount=state.mock.flagged.size;
    const notAnswered=state.mock.questions.filter((item,index)=>state.mock.visited.has(index)&&state.mock.answers[item.id]===undefined&&!state.mock.flagged.has(item.id)).length;
    const notVisited=Math.max(0,total-new Set([...state.mock.visited]).size);
    const candidate=state.session.email || 'aspirenestplatform@gmail.com';
    startMockClock(resource);
    history.replaceState(null,'',`#student/resource/test/${encodeURIComponent(resource.id)}/attempt`);
    els.page.innerHTML=`<section class="live-exam-shell" style="--exam-text-scale:${state.mock.textScale}">
      <header class="live-exam-header">
        <div class="exam-brand-block"><span class="exam-brand-lock"><span class="brand-copy"><strong>AspireNest</strong><small>Academy</small></span></span><div><strong>${escapeHtml(resource.title)}</strong><small>${escapeHtml(subjectById(resource.subject).name)} • ${escapeHtml(resource.chapter)}</small></div></div>
        <div class="exam-header-metrics">
          <div class="exam-metric candidate"><span>CANDIDATE</span><strong>${escapeHtml(candidate)}</strong></div>
          <div class="exam-metric"><span>TIME LEFT</span><strong>◷ <b id="examTimer">${formatMockTime(state.mock.remainingSeconds)}</b></strong></div>
          <div class="exam-metric"><span>QUESTION</span><strong id="examQuestionNumber">${state.mock.index+1}/${total}</strong></div>
          <div class="exam-metric"><span>ANSWERED</span><strong id="examAnswered">${answeredCount}</strong></div>
          <button class="exam-submit-button" data-action="submit-test">Submit Test</button>
        </div>
      </header>
      <div class="live-exam-layout">
        <main class="live-question-workspace">
          <div class="exam-question-toolbar">
            <div class="exam-status-chips"><span class="exam-chip dark">Q${state.mock.index+1} of ${total}</span><span class="exam-chip warning">${examStatusLabel(question)}</span><span class="exam-chip">${state.mock.flagged.has(question.id)?'Marked':'Not Marked'}</span><span class="exam-chip">Current Question</span></div>
            <div class="exam-text-controls"><strong>Text Size</strong><button data-action="exam-text-size" data-size="0.9">A−</button><button data-action="exam-text-size" data-size="1">A</button><button data-action="exam-text-size" data-size="1.12">A+</button></div>
          </div>
          <article class="live-question-card"><span>${state.mock.index+1}</span><h2>${escapeHtml(question.text)}</h2></article>
          <div class="live-option-list">${question.options.map((option,index)=>`<label class="live-option-card ${answered===index?'selected':''}"><input type="radio" name="answer" value="${index}" data-action="select-answer" data-question="${question.id}" ${answered===index?'checked':''}><span>${String.fromCharCode(65+index)}</span><strong>${escapeHtml(option)}</strong></label>`).join('')}</div>
          <footer class="live-exam-actions"><button class="exam-action secondary" data-action="prev-question" ${state.mock.index===0?'disabled':''}>← Previous</button><button class="exam-action secondary" data-action="clear-response">Clear Response</button><button class="exam-action review" data-action="mark-review-next">Mark for Review & Next</button><button class="exam-action next" data-action="save-next">Save & Next</button></footer>
        </main>
        <aside class="live-exam-palette">
          <header><h2>Question Palette</h2><p>${answeredCount}/${total} answered</p></header>
          <div class="exam-range-tabs">${paletteRangeButtons()}</div>
          <div class="exam-palette-grid">${paletteQuestionButtons()}</div>
          <div class="exam-palette-stats">
            <article class="answered"><span>●</span><strong>${answeredCount}</strong><small>Answered</small></article>
            <article class="review"><span>●</span><strong>${reviewCount}</strong><small>Review</small></article>
            <article class="not-answered"><span>●</span><strong>${notAnswered}</strong><small>Not Answered</small></article>
            <article class="not-visited"><span>●</span><strong>${notVisited}</strong><small>Not Visited</small></article>
          </div>
        </aside>
      </div>
    </section>`;
    updateMockClockDom();
  }

  function openSubmitTestConfirmation(resource) {
    const answered=mockAnsweredCount();
    const total=state.mock.questions.length;
    openModal('Submit this test?','Your exact test attempt will be finalized.',`<div class="submit-test-summary"><div><span>Answered</span><strong>${answered}</strong></div><div><span>Unanswered</span><strong>${total-answered}</strong></div><div><span>Marked for review</span><strong>${state.mock.flagged.size}</strong></div><div><span>Time left</span><strong>${formatMockTime(state.mock.remainingSeconds)}</strong></div></div><p class="submit-test-warning">After submission, answers cannot be changed. Result and Review remain attached to this exact test.</p>`,`${button('Continue attempt','secondary','data-action="close-modal"')}${button('Submit now','primary',`data-action="confirm-submit-test" data-id="${resource.id}"`)}`);
  }

  function submitTest(resource,{auto=false}={}) {
    closeModal();
    stopMockClock();
    let score=0;
    state.mock.questions.forEach(question=>{if(state.mock.answers[question.id]===question.answer)score+=Number(question.marks||1);});
    const total=state.mock.questions.reduce((sum,question)=>sum+Number(question.marks||1),0);
    state.mock.submitted=true;
    state.mock.result={score,total,accuracy:total?Math.round((score/total)*100):0,answered:mockAnsweredCount(),review:state.mock.flagged.size,autoSubmitted:auto};
    storage.setItem(STORAGE.mockAttempt,JSON.stringify({resourceId:resource.id,answers:state.mock.answers,flagged:[...state.mock.flagged],result:state.mock.result,submittedAt:new Date().toISOString()}));
    adapter.recordAttempt({resourceId:resource.id,action:'SUBMIT',result:state.mock.result,answers:state.mock.answers,flagged:[...state.mock.flagged]});
    renderTestResult(resource);
  }

  function renderTestResult(resource) {
    setFocusedExamMode(false);
    stopMockClock();
    const totalQuestions=state.mock.questions.length||(/mega/i.test(resource.title)?200:30);
    const result=state.mock.result||{score:0,total:totalQuestions,accuracy:0,answered:0,review:0};
    els.page.innerHTML=`<div class="exact-workspace result-workspace">${exactWorkspaceHeader(resource,'RESULT')}
      <section class="result-hero"><span class="eyebrow">ATTEMPT SUBMITTED</span><strong>${result.score}/${result.total}</strong><h2>${result.accuracy}% accuracy</h2><p>This result belongs only to ${escapeHtml(resource.title)}.</p><div class="result-actions">${button('Review answers','primary','data-action="review-test"')}${button('Attempt again','secondary','data-action="restart-test"')}${button('Open result history','secondary','data-go="success/history"')}</div></section>
      <div class="dashboard-grid">${infoCard('Correct',String(result.score))}${infoCard('Incorrect',String(Math.max(0,result.total-result.score)))}${infoCard('Unanswered',String(Math.max(0,totalQuestions-(result.answered||0))))}${infoCard('Marked for review',String(result.review||0))}</div>
    </div>`;
  }

  function renderTestReview(resource) {
    setFocusedExamMode(false);
    const questions=state.mock.questions||[];
    els.page.innerHTML=`<div class="exact-workspace review-workspace">${exactWorkspaceHeader(resource,'ANSWER REVIEW',button('Back to result','secondary','data-action="back-to-result"'))}
      <div class="review-list">${questions.map((question,index)=>{const selected=state.mock.answers[question.id];const correct=selected===question.answer;return `<article class="review-card ${correct?'correct':'incorrect'}"><header><span>Question ${index+1}</span><strong>${correct?'Correct':selected===undefined?'Unanswered':'Incorrect'}</strong></header><h3>${escapeHtml(question.text)}</h3><p>Your answer: ${selected===undefined?'Not answered':`${String.fromCharCode(65+selected)}. ${escapeHtml(question.options[selected])}`}</p><p>Correct answer: ${String.fromCharCode(65+question.answer)}. ${escapeHtml(question.options[question.answer])}</p><div class="reader-callout"><strong>Revision note:</strong> Review the linked concept in AspireNest Notes.</div></article>`;}).join('')}</div>
    </div>`;
  }

