    if (action === 'save') { const wasSaved=state.saved.has(id),resource=resourceById(id);if(wasSaved){state.saved.delete(id);toast('Removed from Saved','☆');}else{state.saved.add(id);toast('Saved for quick access','★');}persistSets();renderPage();try{const sync=await adapter.recordProgress?.({resourceId:id,resourceType:resource?.type||'',progress:Number(resource?.progress||0),saved:!wasSaved,continueState:{route:resource?exactRoute(resource):''}});if(sync&&sync.ok===false)throw new Error(sync.code||'SAVE_SYNC_DENIED');}catch(error){if(wasSaved)state.saved.add(id);else state.saved.delete(id);persistSets();renderPage();lp4OperationFailure('save-resource',error);}return; }
    if (action === 'revision') { state.revision.add(id);persistSets();toast('Added to Revision Queue','↻');return; }
    if (action === 'clear-search') {state.query='';els.search.value='';renderPage();return;}
    if (action === 'back-to-library') { setFocusedExamMode(false);stopMockClock();setIntelliPlayerFocus(false);stopPlayerClock();setRole('student');return setRoute('learning','library'); }
    if (action === 'note-progress') { const resource=resourceById(state.selectedResourceId);const progress=setReaderProgress(resource,readerProgress(resource)+8);document.getElementById('noteProgressBar')?.style.setProperty('width',`${progress}%`);adapter.recordProgress({resourceId:resource?.id,resourceType:resource?.type||'note',progress,cursor:{page:Number(state.reader?.page||0),readerMode:state.reader?.mode||'book'},continueState:{route:resource?exactRoute(resource):'',page:Number(state.reader?.page||0)}});toast(`Reading progress saved: ${progress}%`);return; }
    if (action === 'reader-mode') { state.reader.mode=node.dataset.mode==='study'?'study':'book';persistReaderState();renderActiveReader();toast(`${state.reader.mode==='book'?'Book View':'Study View'} active`,'N');return; }
    if (action === 'reader-layout') { state.reader.layout=['continuous','single','spread'].includes(node.dataset.layout)?node.dataset.layout:'spread';if(state.reader.layout==='spread')state.reader.page=Math.floor(state.reader.page/2)*2;persistReaderState();renderActiveReader();return; }
