    if (action === 'save-reader-note') { const form=document.getElementById('readerNoteForm');if(!form?.reportValidity())return;addStudyRecord('notes',{text:String(form.elements.selected.value||'').trim(),note:String(form.elements.note.value||'').trim()});closeModal();renderActiveReader();toast('Personal note saved','✦');return; }
    if (action === 'save-reader-flashcard') { const form=document.getElementById('readerFlashcardForm');if(!form?.reportValidity())return;addStudyRecord('flashcards',{front:String(form.elements.front.value||'').trim(),back:String(form.elements.back.value||'').trim()});closeModal();renderActiveReader();toast('Flashcard created','✦');return; }
    if (action === 'toggle-video') { state.player.playing=!state.player.playing;persistPlayerState();renderVideoWorkspace(resourceById(state.selectedResourceId));return; }
    if (action === 'advance-video') { state.videoProgress=Math.min(100,state.videoProgress+10);persistPlayerState();updatePlayerProgressUI();adapter.recordProgress({resourceId:state.selectedResourceId,resourceType:resourceById(state.selectedResourceId)?.type||'video',progress:state.videoProgress,cursor:{seconds:Math.round(state.videoProgress*14.4)},continueState:{route:resourceById(state.selectedResourceId)?exactRoute(resourceById(state.selectedResourceId)):'',seconds:Math.round(state.videoProgress*14.4)}});return; }
