    if (action === 'player-volume') { state.player.volume=state.player.volume===0?80:state.player.volume===80?40:0;persistPlayerState();renderVideoWorkspace(resourceById(state.selectedResourceId));return; }
    if (action === 'player-captions') { state.player.captions=!state.player.captions;persistPlayerState();renderVideoWorkspace(resourceById(state.selectedResourceId));return; }
    if (action === 'player-quality') { const values=['Auto','1080p','720p','480p'];const index=values.indexOf(state.player.quality);state.player.quality=values[(index+1)%values.length];persistPlayerState();renderVideoWorkspace(resourceById(state.selectedResourceId));return; }
    if (action === 'player-transcript') { state.player.transcript=!state.player.transcript;persistPlayerState();renderVideoWorkspace(resourceById(state.selectedResourceId));return; }
    if (action === 'player-chapter') { state.player.chapter=Number(node.dataset.index||0);state.videoProgress=Number(node.dataset.progress||0);persistPlayerState();renderVideoWorkspace(resourceById(state.selectedResourceId));return; }
    if (action === 'player-focus') { setIntelliPlayerFocus(!state.player.focus);renderVideoWorkspace(resourceById(state.selectedResourceId));return; }
    if (action === 'player-fullscreen') { const target=document.querySelector('.intelliplayer-shell');if(!document.fullscreenElement)target?.requestFullscreen?.();else document.exitFullscreen?.();return; }
