    if (action === 'player-bookmark') { state.playerRecords.bookmarks.push({progress:state.videoProgress,resourceId:state.selectedResourceId,createdAt:new Date().toISOString()});persistPlayerRecords();adapter.recordStudyAction({resourceId:state.selectedResourceId,action:'VIDEO_BOOKMARK',record:{progress:state.videoProgress}});renderVideoWorkspace(resourceById(state.selectedResourceId));toast('Video timestamp bookmarked','★');return; }
    if (action === 'save-player-record') { const form=document.getElementById('playerRecordForm');if(!form?.reportValidity())return;const kind=form.elements.kind.value==='doubt'?'doubts':'notes';const record={resourceId:state.selectedResourceId,progress:state.videoProgress,text:String(form.elements.text.value||'').trim(),createdAt:new Date().toISOString()};state.playerRecords[kind].push(record);persistPlayerRecords();adapter.recordStudyAction({resourceId:state.selectedResourceId,action:kind==='doubts'?'VIDEO_DOUBT':'VIDEO_NOTE',record});closeModal();renderVideoWorkspace(resourceById(state.selectedResourceId));toast(kind==='doubts'?'Timestamp doubt saved':'Class note saved','✦');return; }
    if (action === 'player-save') { persistPlayerState();adapter.recordProgress({resourceId:state.selectedResourceId,progress:state.videoProgress});toast(`Video progress saved: ${state.videoProgress}%`,'▶');return; }
