  const studentPaymentRowsV16=studentPaymentRows;
  studentPaymentRows=function(){return [];};
  openStudentPaymentHistory=function(){setRole('student');setRoute('home','payments');};

  const renderStudentHomeV16=renderStudentHome;
  renderStudentHome=function(context){
    if(context==='overview')return renderStudentOverviewV17();
    if(context==='today')return renderStudentTodayV17();
    if(context==='notifications')return renderStudentNotificationsV17();
    if(context==='account-security')return renderStudentAccountSecurityV17();
    if(context==='payments')return renderStudentPaymentsV17();
    return renderStudentHomeV16(context);
  };
  const renderStudentLearningV16=renderStudentLearning;
  renderStudentLearning=function(context){
    if(context==='courses')return renderStudentCoursesV17();
    if(context==='assigned')return renderStudentAssignmentsV17();
    if(context==='revision')return renderStudentRevisionV17();
    if(context==='saved')return renderStudentSavedV17();
    return renderStudentLearningV16(context);
  };
  const renderSuccessV16=renderSuccess;
  renderSuccess=function(context){
    if(context==='overview')return els.page.innerHTML=renderStudentProgressV17()||'';
    if(context==='results')return renderStudentResultsV17();
    if(context==='mistake-book')return renderStudentMistakeBookV17();
    return renderSuccessV16(context);
  };
  const contextCountV16=contextCount;
  contextCount=function(role,parent,context){
    if(role==='student'){
      if(parent==='home'&&context==='notifications')return studentV17Unread();
      if(parent==='home'&&context==='account-security')return 1;
      if(parent==='home'&&context==='payments')return 0;
      if(parent==='learning'&&context==='courses')return 1;
      if(parent==='learning'&&context==='revision')return state.revision.size+(state.studyRecords.flashcards?.length||0);
      if(parent==='learning'&&context==='assigned')return studentV17ActiveAssignments().length;
      if(parent==='success'&&context==='mistake-book')return state.mock.result?.incorrect||3;
    }
    return contextCountV16(role,parent,context);
  };
  const roleAccountMenuMarkupV16=roleAccountMenuMarkup;
  roleAccountMenuMarkup=function(){
    if(state.role!=='student'||!state.session.authenticated)return roleAccountMenuMarkupV16();
    const name=state.studentProfile.fullName||state.session.displayName||state.session.email||'AspireNest Student';
    return `<div class="account-profile role-student"><span class="avatar">${initials(name)}</span><div><strong>${escapeHtml(name)}</strong><small>STUDENT workspace • ${escapeHtml(state.session.plan||'FREE')}</small></div></div><div class="account-menu-section"><small>STUDENT ACCOUNT</small><button class="popover-item" data-go="home/profile">♙ My Student Profile</button><button class="popover-item" data-go="home/account-security">⚙ Account & Devices</button><button class="popover-item" data-go="home/notifications">◉ Notifications (${studentV17Unread()})</button><button class="popover-item" data-go="home/my-access">✓ My Access</button><button class="popover-item" data-go="home/access-requests">◎ Access Requests</button><button class="popover-item" data-go="home/redeem-access">⌁ Redeem Access</button><button class="popover-item" data-go="home/payments">₹ Payments & Receipts</button><button class="popover-item" data-action="edit-student-preferences">✦ Learning Preferences</button></div><button class="popover-item" data-action="switch-workspace">⇄ Switch workspace</button><button class="popover-item" data-action="logout">↗ Sign out preview</button>`;
  };
  const showNotificationsV16=showNotifications;
  showNotifications=function(){
    if(state.role!=='student')return showNotificationsV16();
    closePopovers();const node=document.createElement('div');node.className='notification-panel role-notification-panel';
    const items=state.studentV17.notifications.slice(0,5);
    node.innerHTML=`<div class="popover-heading">Student updates • ${studentV17Unread()} unread</div>${items.map(item=>`<button class="notice role-notice" data-go="${escapeHtml(item.route)}"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.copy)}</small></button>`).join('')}<button class="popover-item strong" data-go="home/notifications"><strong>Open Notification Center</strong><small>History, preferences and delivery status</small></button>`;document.body.appendChild(node);
  };

  document.addEventListener('click',event=>{
    const node=event.target.closest('[data-v17-action]');if(!node)return;
    event.preventDefault();event.stopImmediatePropagation();closePopovers();
    const action=node.dataset.v17Action,id=node.dataset.id||'';
    if(action==='toggle-task'){
      const task=state.studentV17.tasks.find(item=>item.id===id);if(!task)return;
      task.status=task.status==='Completed'?'Not started':'Completed';persistStudentV17();renderAll();toast(task.status==='Completed'?'Task completed':'Task reopened',task.status==='Completed'?'✓':'↻');return;
    }
    if(action==='complete-assignment'){
      if(!state.studentV17.completedAssignments.includes(id))state.studentV17.completedAssignments.push(id);persistStudentV17();renderAll();toast('Assignment marked complete for Mentor review','✓');return;
    }
    if(action==='notification-read'){
      const item=state.studentV17.notifications.find(entry=>entry.id===id);if(item)item.read=true;persistStudentV17();renderAll();return;
    }
    if(action==='notifications-read-all'){state.studentV17.notifications.forEach(item=>item.read=true);persistStudentV17();renderAll();toast('All notifications marked read','✓');return;}
    if(action==='notification-preferences'){
      const p=state.studentV17.notificationPreferences;openModal('Notification Preferences','Choose in-app learning updates. automatic Gmail remains disabled until Admin provider activation.',`<form id="studentV17NotificationForm" class="admin-form-grid"><label class="admin-form-field"><span>Learning reminders</span><select name="learning"><option ${p.learning?'selected':''}>On</option><option ${!p.learning?'selected':''}>Off</option></select></label><label class="admin-form-field"><span>Mentor updates</span><select name="mentor"><option ${p.mentor?'selected':''}>On</option><option ${!p.mentor?'selected':''}>Off</option></select></label><label class="admin-form-field"><span>Live reminders</span><select name="live"><option ${p.live?'selected':''}>On</option><option ${!p.live?'selected':''}>Off</option></select></label><label class="admin-form-field"><span>Access decisions</span><select name="access"><option ${p.access?'selected':''}>On</option><option ${!p.access?'selected':''}>Off</option></select></label><label class="admin-form-field"><span>Weekly summary</span><select name="weeklySummary"><option ${p.weeklySummary?'selected':''}>On</option><option ${!p.weeklySummary?'selected':''}>Off</option></select></label><label class="admin-form-field"><span>Email provider</span><input value="DISABLED" disabled></label></form>`,`${button('Cancel','secondary','data-action="close-modal"')}${button('Save preferences','primary','data-v17-action="save-notification-preferences"')}`);return;
    }
    if(action==='save-notification-preferences'){
      const form=document.getElementById('studentV17NotificationForm');if(!form)return;const data=Object.fromEntries(new FormData(form).entries());['learning','mentor','live','access','weeklySummary'].forEach(key=>state.studentV17.notificationPreferences[key]=data[key]==='On');persistStudentV17();closeModal();renderAll();toast('Notification preferences saved','◉');return;
    }
    if(action==='signout-other-devices'){toast('Server-side session revocation is ready for Firebase integration','⚙');return;}
    if(action==='request-data-export'||action==='request-account-review'){
      const request={id:`student-account-${Date.now()}`,type:action==='request-data-export'?'DATA_EXPORT':'ACCOUNT_REVIEW',status:'Prepared',createdAt:new Date().toISOString()};state.studentV17.accountRequests.unshift(request);persistStudentV17();toast(action==='request-data-export'?'Data export request prepared':'Account review request prepared','↗');return;
    }
    if(action==='open-attempt-review'){
      const resource=resourceById(id);if(!resource)return;state.mock.resourceId=resource.id;state.mock.questions=buildMockQuestions(resource);state.mock.answers={};state.mock.result={score:24,total:30,correct:24,incorrect:6,unanswered:0,accuracy:80};renderTestReview(resource);return;
    }
  },true);

