  state.mentorV18=readJson(MENTOR_V18_STORAGE,MENTOR_V18_DEFAULT);
  function persistMentorV18(){storage.setItem(MENTOR_V18_STORAGE,JSON.stringify(state.mentorV18));}
  function mentorV18Audit(action,entity,detail){state.mentorV18.audit.unshift({id:`mentor-audit-${Date.now()}`,action,entity,detail,createdAt:new Date().toLocaleString('en-IN')});persistMentorV18();}
  function ensureMentorContext(parent,id,label,icon,afterId=''){
    const list=MENTOR_CONTEXTS[parent];if(!Array.isArray(list)||list.some(item=>item[0]===id))return;
    const entry=[id,label,icon];const index=afterId?list.findIndex(item=>item[0]===afterId):-1;
    if(index>=0)list.splice(index+1,0,entry);else list.push(entry);
  }
  ensureMentorContext('home','today','Today','☀','overview');
  ensureMentorContext('home','notifications','Notifications','◉','activity');
  ensureMentorContext('learners','attention','Attention queue','!','all');
  ensureMentorContext('learners','groups','Learner groups','▦','progress');
  ensureMentorContext('assignments','drafts','Drafts','▤','active');
  ensureMentorContext('content','collections','Collections','▦','saved');
  ensureMentorContext('questions','follow-up','Follow-up','↻','open');
  ensureMentorContext('live','calendar','Calendar','▦','upcoming');
  ensureMentorContext('profile','preferences','Mentor Preferences','⚙','social');
  ensureMentorContext('profile','account','Account & Devices','◉','visibility');
  ensureMentorContext('analytics','workload','Workload','▦','engagement');
  ensureMentorContext('analytics','outcomes','Outcomes','✓','workload');
