      const item=state.mentorAssignments.find(entry=>entry.id===id);if(!item)return;item.status='Archived';persistMentorOperations();mentorV18Audit('ARCHIVE_ASSIGNMENT',id,item.title);closeModal();renderAll();toast('Assignment archived; learner access unchanged','↻');return;
