  const PUBLIC_V19_KEY='aspirenest_public_os_v19';
  state.publicV19=readJson(PUBLIC_V19_KEY,{
    contactRequests:[],
    planRequests:[],
    waitlist:[],
    viewedRoutes:[],
    consent:{essential:true,analytics:false,marketing:false}
  });
  function persistPublicV19(){
    localStorage.setItem(PUBLIC_V19_KEY,JSON.stringify(state.publicV19));
  }
  function publicV19RecordRoute(parent,context){
    const route=`#public/${parent}/${context}`;
    state.publicV19.viewedRoutes=[route,...state.publicV19.viewedRoutes.filter(item=>item!==route)].slice(0,20);
    persistPublicV19();
  }
