    return `<section class="public-v19-catalog-summary"><div><span class="eyebrow">PUBLIC DISCOVERY</span><h2>${list.length} published resource${list.length===1?'':'s'} in this view</h2><p>Every card keeps the exact canonical resource ID through preview and sign-in.</p></div><div><article><strong>${open}</strong><small>Open preview</small></article><article><strong>${protectedCount}</strong><small>Access-aware</small></article><article><strong>${context==='all'?6:1}</strong><small>Learning type${context==='all'?'s':''}</small></article></div></section>`;
