    els.page.innerHTML=`${publicV19MarketingHero()}${publicV19ProofStrip()}${renderExperienceRibbon('public')}${publicV19EngineGrid()}${renderPublicMentorSpotlight()}${renderExperienceTv()}${renderWeeklyExperience()}${renderWhatsNew()}${publicV19FinalCta()}${publicV19Footer()}`;
