    if(!resend&&!form?.reportValidity())return;
    state.authV20.resetEmail=email;persistAuthV20();await adapter.requestPasswordReset?.({email,returnTo:authDestinationV20()});setAuthRouteV20('reset-sent');toast('Password reset request prepared','✉');
