  document.addEventListener('click',async event=>{
    const node=event.target.closest('[data-auth-action]');if(!node)return;
    event.preventDefault();event.stopImmediatePropagation();closePopovers();
    const action=node.dataset.authAction;
    if(action==='go-login')return setAuthRouteV20('login');
    if(action==='go-create'){state.authV20.createStep=1;persistAuthV20();return setAuthRouteV20('create-account');}
    if(action==='create-next')return saveCreateIdentityV21();
    if(action==='create-back'){state.authV20.createStep=1;persistAuthV20();renderAll();window.scrollTo({top:0,behavior:'smooth'});return;}
    if(action==='forgot')return setAuthRouteV20('forgot-password');
    if(action==='back-public'){state.publicParent='home';state.publicContext='overview';history.replaceState(null,'','#public/home/overview');return renderAll();}
    if(action==='submit-login')return submitLoginV20();
    if(action==='submit-create')return submitCreateV20();
    if(action==='google')return googleAuthV20();
    if(action==='verify-demo')return verifyDemoV20();
    if(action==='resend-verification'){await adapter.resendVerification?.({email:state.authV20.pendingAccount?.email||''});state.authV20.verificationSentAt=new Date().toISOString();persistAuthV20();return toast('Verification link prepared again','✉');}
    if(action==='submit-forgot')return submitForgotV20(false);
    if(action==='submit-forgot-again')return submitForgotV20(true);
    if(action==='toggle-password'){
      const input=document.getElementById(node.dataset.target);if(!input)return;const reveal=input.type==='password';input.type=reveal?'text':'password';node.textContent=reveal?'Hide':'Show';return;
    }
  },true);


