      {id:'attempt-v22-2',testId:'test-cdp-growth',learner:'rahul@example.com',score:24,total:30,accuracy:80,correct:24,incorrect:6,unanswered:0,duration:'21 min',submittedAt:'02 Aug 2026 • 4:10 PM',status:'Completed',released:true}
