  function v22TestById(id){return mockV22.tests.find(test=>test.id===id);}
  function v22QuestionById(id){return mockV22.questionBank.find(question=>question.id===id);}
  function v22QuestionsForTest(test){
    if(!test)return[];
    const bank=(test.questionIds||[]).map(v22QuestionById).filter(Boolean);
    const inline=(test.inlineQuestions||[]).map((q,i)=>v22NormalizeQuestion(q,i));
    return [...bank,...inline].slice(0,Number(test.config?.totalQuestions)||bank.length+inline.length);
  }
  function v22NormalizeQuestion(question,index=0){
    const options=Array.isArray(question.options)?question.options:[question['Option A']||question.optionA,question['Option B']||question.optionB,question['Option C']||question.optionC,question['Option D']||question.optionD].filter(value=>value!==undefined&&value!==null&&String(value).trim()!=='').map(String);
    let answer=question.answer;
    if(!Number.isInteger(answer)){
      const raw=String(question.correctAnswer??question['Correct Answer']??question.correctIndex??'').trim();
      const normalized=raw.replace(/^option\s*/i,'').trim().toUpperCase();
      answer=/^[A-Z]$/.test(normalized)?normalized.charCodeAt(0)-65:Number.isFinite(Number(raw))?Math.max(0,Number(raw)-(/^[1-9]\d*$/.test(raw)?1:0)):0;
    }
    answer=Math.max(0,Math.min(options.length-1,Number(answer)||0));
    return {id:String(question.id||`q-${Date.now()}-${index}`),number:Number(question.number||question['Question Number']||index+1),text:String(question.text||question.question||question.Question||''),options,answer,explanation:String(question.explanation||question.Explanation||''),difficulty:String(question.difficulty||question['Difficulty Level']||'Moderate'),questionType:String(question.questionType||question['Question Type']||'Single Correct'),language:String(question.language||question.Language||'English'),tag:String(question.tag||question.Tag||''),positiveMarks:Number(question.positiveMarks||question['Positive Marks']||question.marks||1),negativeMarks:Number(question.negativeMarks||question['Negative Marks']||0),status:String(question.status||question['Question Status']||'Draft'),saveToQuestionBank:/^(yes|true|1)$/i.test(String(question.saveToQuestionBank??question['Save To Question Bank']??'yes')),source:String(question.source||'Manual'),version:Number(question.version||1),updatedAt:question.updatedAt||new Date().toLocaleString('en-IN')};
  }
  function v22ConfigToResource(test){
    const subjectMap={'Child Development & Pedagogy':'cdp','English':'english','Hindi':'hindi','Mathematics':'maths','EVS':'evs','Social Science':'social'};
    return {id:test.id,type:'test',title:test.config.title,subtitle:`${test.config.subject} • ${test.config.chapter}`,subject:subjectMap[test.config.subject]||test.subjectId||'cdp',chapter:test.config.chapter,requiredPlan:test.config.plan||test.config.access||'PREMIUM',accessState:test.accessState||'open',status:test.config.status==='Published'?'Published':test.config.status,duration:`${test.config.durationMinutes} min`,assigned:false,recent:false,saved:false,progress:0,canonicalRoute:`/ctet-tet/mock-tests/start/${test.id}`,description:'Exact Mock Test configured through the complete Drive-native Admin Mock Test Studio.'};
  }
  function v22SyncTest(test){
    const resource=v22ConfigToResource(test);
    const resourceIndex=resources.findIndex(item=>item.id===test.id);
    if(resourceIndex>=0)Object.assign(resources[resourceIndex],resource);else resources.push(resource);
    const adminIndex=state.adminResources.findIndex(item=>item.id===test.id);
    const adminRecord={id:test.id,title:test.config.title,type:'test',subject:resource.subject,access:resource.requiredPlan,status:test.config.status,updated:test.updatedAt,owner:test.owner||'Admin',canonicalRoute:resource.canonicalRoute};
    if(adminIndex>=0)Object.assign(state.adminResources[adminIndex],adminRecord);else state.adminResources.push(adminRecord);
    persistAdminOperations();
  }
