  document.addEventListener('paste',event=>{const test=v22TestById(state.mock.resourceId);if(document.body.classList.contains('focused-exam-mode')&&test?.config?.copyPasteProtection){event.preventDefault();toast('Paste is disabled during this configured attempt','!');}},true);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='hidden'||!document.body.classList.contains('focused-exam-mode'))return;const test=v22TestById(state.mock.resourceId);if(!test?.config?.tabSwitchDetection)return;state.mock.violations=Number(state.mock.violations||0)+1;mockV23.violations.unshift({testId:test.id,attemptId:state.mock.attemptId,time:new Date().toISOString(),type:'TAB_HIDDEN'});persistMockDraft('TAB_SWITCH');v23Log('TAB_SWITCH',test.id,`count=${state.mock.violations}`);if(test.config.autoSubmitOnViolation){stopMockClock();submitTest(resourceById(test.id),{auto:true,reason:'VIOLATION'});}});


  // V24 — Mock safe-exit / pause-resume / large-test scalability + final Notes operations.
  const NOTES_V24_STORAGE='aspirenest_notes_v24_operations_v1';
  STORAGE.notesV24=NOTES_V24_STORAGE;
  const cloneV24=value=>JSON.parse(JSON.stringify(value));
  const notePdfPathV24=id=>`assets/notes/${id}.pdf`;
  function noteDefaultPagesV24(resource){
    if(resource.id==='note-child-development')return cloneV24(INTELLIBOOK_PAGES);
    const title=resource.title||'AspireNest Learning Note',chapter=resource.chapter||resource.subtitle||'Overview';
    return [
      {id:'overview',number:1,title:`${title}: Overview`,paragraphs:[resource.description||`Structured learning overview for ${title}.`,`This note keeps exact resource identity, progress, study tools and mentor context inside AspireNest IntelliBook.`],callout:`Study focus: Identify the core idea, key terms and exam connection for ${chapter}.`},
      {id:'concepts',number:2,title:'Core Concepts',paragraphs:[`The central concepts of ${chapter} are organised from foundation to application.`,`Use the highlight, personal note, doubt and flashcard tools to convert reading into active revision.`],bullets:['Definition and scope','Key terms','Concept relationships','Classroom or exam application']},
      {id:'application',number:3,title:'Application & Exam Link',paragraphs:[`Apply the concept through examples, comparisons and short recall prompts.`,`Connect each idea with the exact syllabus objective and likely question pattern.`],callout:'Exam checkpoint: Explain the concept in one sentence and identify one common misconception.'},
      {id:'checkpoint',number:4,title:'Revision Checkpoint',paragraphs:[`Review saved highlights, notes, flashcards and doubts from this exact note.`,`Complete the checkpoint before marking the section as revised.`],mcq:{question:`Which action best supports learning from ${chapter}?`,options:['Reading once without recall','Connecting concepts, examples and revision','Ignoring difficult points','Memorising only headings'],answer:1}}
    ];
  }
  function noteRecordFromResourceV24(resource,index=0){
    return {
      id:resource.id,resourceId:resource.id,title:resource.title,subtitle:resource.subtitle||resource.title,
      subject:resource.subject||'cdp',chapter:resource.chapter||'General',access:resource.requiredPlan||'PREMIUM',
      language:'English',delivery:'Hybrid IntelliText + PDF',status:resource.status||'Draft',description:resource.description||'',
      duration:resource.duration||'Open resource',canonicalRoute:resource.canonicalRoute||`/ctet-tet/notes/read/${resource.id}`,
      pages:noteDefaultPagesV24(resource),pdf:{enabled:true,path:notePdfPathV24(resource.id),name:`${resource.title}.pdf`,status:'Ready'},
      cover:{title:resource.title,subtitle:resource.subtitle||resource.chapter||'',accent:index%2?'blue':'orange'},
      settings:{bookView:true,studyView:true,continuous:true,single:true,spread:true,search:true,downloadPdf:true,highlights:true,underlines:true,personalNotes:true,doubts:true,bookmarks:true,flashcards:true,revision:true},
      validation:{status:resource.status==='Published'?'Ready':'Needs validation',errors:[],warnings:[]},
      version:resource.status==='Published'?3:1,versions:[{version:resource.status==='Published'?3:1,status:resource.status||'Draft',createdAt:'02 Aug 2026',actor:'Admin',reason:'Initial canonical note version'}],
      assets:[{id:`asset-${resource.id}-pdf`,type:'PDF fallback',path:notePdfPathV24(resource.id),status:'Ready'}],
      updatedAt:'03 Aug 2026',owner:'Admin',samplePublic:true
    };
  }
  const noteV24=(()=>{
    const saved=readJson(NOTES_V24_STORAGE,null)||{};
    const records=saved.records||{};
    resources.filter(item=>item.type==='note').forEach((resource,index)=>{if(!records[resource.id])records[resource.id]=noteRecordFromResourceV24(resource,index);});
    return {records,view:saved.view||'list',filter:saved.filter||'ALL',builderStep:saved.builderStep||1,draftId:saved.draftId||'',draft:saved.draft||null,selectedPage:Number(saved.selectedPage||0),imports:saved.imports||[],audit:saved.audit||[],progressByResource:saved.progressByResource||{'note-child-development':state.noteProgress}};
  })();
