  const modulesV25=(()=>{const saved=readJson(MODULES_V25_STORAGE,null);if(!saved)return cloneV25(defaultModulesV25);const merged=cloneV25(defaultModulesV25);Object.assign(merged,saved);merged.videos={...defaultModulesV25.videos,...(saved.videos||{})};merged.live={...defaultModulesV25.live,...(saved.live||{})};merged.currentAffairs={...defaultModulesV25.currentAffairs,...(saved.currentAffairs||{})};merged.roadmaps={...defaultModulesV25.roadmaps,...(saved.roadmaps||{})};merged.student={...defaultModulesV25.student,...(saved.student||{})};merged.mentor={...defaultModulesV25.mentor,...(saved.mentor||{})};return merged;})();
  state.modulesV25=modulesV25;
