  function liveStateV25(record){const now=Date.now(),start=new Date(record.startAt).getTime(),end=new Date(record.endAt).getTime(),open=start-Number(record.joinWindowMinutes||10)*60000,late=start+Number(record.lateJoinMinutes||20)*60000;if(record.status==='Cancelled')return 'Cancelled';if(now<open)return 'Upcoming';if(now>=open&&now<=late)return 'Join window';if(now>late&&now<=end)return 'Live now';if(now>end)return record.replayResourceId?'Replay available':'Ended';return 'Upcoming';}
