  document.addEventListener('click',event=>{const node=event.target.closest('[data-v25-action]');if(!node)return;event.preventDefault();event.stopImmediatePropagation();const action=node.dataset.v25Action,type=node.dataset.type,id=node.dataset.id;const record=type&&id?moduleRecordV25(type,id):null;
    if(action==='module-create'){openModuleBuilderV25(type);return;}if(action==='module-edit'){closeModal();openModuleBuilderV25(type,id);return;}if(action==='module-form-save'){saveModuleFormV25(false);return;}if(action==='module-form-validate'){saveModuleFormV25(true);return;}if(action==='module-filter'){modulesV25.filters[type]=node.dataset.filter;persistModulesV25();renderModuleAdminV25(type);return;}if(action==='module-preview'){modulePreviewV25(type,record);return;}if(action==='module-more'){moduleMoreV25(type,record);return;}if(action==='module-open-workspace'){closeModal();setRole('student');history.replaceState(null,'',`#student/resource/${type==='current-affairs'?'current-affairs':type}/${id}`);renderExactWorkspace(resourceById(id));return;}if(action==='module-validate-record'){record.validation=moduleValidationV25(type,record);moduleAuditV25('VALIDATE',type,id,record.validation.status);persistModulesV25();closeModal();renderModuleAdminV25(type);return;}if(action==='module-publish'){const report=moduleValidationV25(type,record);record.validation=report;if(report.errors.length)return toast('Publish blocked: validation errors remain','!');if(type==='live')record.publicationStatus='Published';else record.status='Published';record.version=Number(record.version||0)+1;record.updatedAt=nowV25();syncModuleResourceV25(type,record);moduleAuditV25('PUBLISH',type,id,`v${record.version}`);adapter[`publish${type==='current-affairs'?'CurrentAffairs':type[0].toUpperCase()+type.slice(1)}`]?.({resourceId:id,record:cloneV25(record)}).catch?.(()=>{});persistModulesV25();renderModuleAdminV25(type);return;}if(action==='module-unpublish'){if(type==='live')record.publicationStatus='Unpublished';else record.status='Unpublished';record.updatedAt=nowV25();syncModuleResourceV25(type,record);moduleAuditV25('UNPUBLISH',type,id,'Protected delivery removed from discovery');persistModulesV25();renderModuleAdminV25(type);return;}if(action==='module-duplicate'){const copy=cloneV25(record),nextId=`${id}-copy-${Date.now().toString().slice(-5)}`;copy.id=nextId;copy.resourceId=nextId;copy.title=`${record.title} — Copy`;copy.status=type==='live'?'Scheduled':'Draft';if(type==='live')copy.publicationStatus='Draft';copy.version=0;copy.updatedAt=nowV25();moduleCollectionV25(type)[nextId]=copy;syncModuleResourceV25(type,copy);moduleAuditV25('DUPLICATE',type,nextId,`From ${id}`);persistModulesV25();closeModal();renderModuleAdminV25(type);return;}if(action==='module-archive'){if(type==='live')record.publicationStatus='Archived';else record.status='Archived';syncModuleResourceV25(type,record);moduleAuditV25('ARCHIVE',type,id,'Soft archive');persistModulesV25();closeModal();renderModuleAdminV25(type);return;}if(action==='module-restore'){if(type==='live')record.publicationStatus='Draft';else record.status='Draft';syncModuleResourceV25(type,record);moduleAuditV25('RESTORE',type,id,'Restored as draft');persistModulesV25();closeModal();renderModuleAdminV25(type);return;}if(action==='module-audit-record'){openModal('Module audit history',`Exact history for ${record.title}.`,adminTable(['Time','Action','Actor','Detail'],modulesV25.audit.filter(item=>item.resourceId===id).map(item=>`<tr><td>${escapeHtml(item.time)}</td><td>${escapeHtml(item.action)}</td><td>${escapeHtml(item.actor)}</td><td>${escapeHtml(item.detail)}</td></tr>`)),button('Close','primary','data-action="close-modal"'));return;}
    if(action==='video-processing-report'){openModuleReportV25('video',moduleRecordV25('video',id));return;}if(action==='live-provider-report'){openModuleReportV25('live',moduleRecordV25('live',id));return;}if(action==='roadmap-day-report'){openModuleReportV25('roadmap',moduleRecordV25('roadmap',id));return;}if(action==='ca-edit-pages'){openCaPageEditorV25(moduleRecordV25('current-affairs',id));return;}if(action==='ca-save-pages'){saveCaPagesV25(moduleRecordV25('current-affairs',id));return;}if(action==='ca-add-correction'){openCorrectionEditorV25(moduleRecordV25('current-affairs',id));return;}if(action==='ca-save-correction'){saveCorrectionV25(moduleRecordV25('current-affairs',id));return;}
    if(action==='video-attachment'){toast('Protected attachment request prepared','▤');adapter.downloadVideoAttachment?.({resourceId:id,resourceType:'video',attachmentId:node.dataset.attachment}).catch?.(error=>lp4OperationFailure('downloadVideoAttachment',error));return;}if(action==='video-source-info'){const item=moduleRecordV25('video',id);openModal('Video source connection','Provider details remain protected from Public discovery.',`<div class="continuity-note"><strong>${escapeHtml(item.sourceType.replace(/_/g,' '))}</strong><p>${safeUrlV25(item.sourceUrl)?'Valid provider URL configured. Production uses signed/authorised delivery.':'Protected Storage path configured.'}</p></div>`,button('Close','primary','data-action="close-modal"'));return;}if(action==='ca-source-register'){openSourceRegisterV25(moduleRecordV25('current-affairs',id));return;}if(action==='ca-corrections'){const item=moduleRecordV25('current-affairs',id);openModal('Correction history','Corrections never silently replace the source trail.',(item.corrections||[]).length?adminTable(['Time','Correction','Actor'],item.corrections.map(row=>`<tr><td>${escapeHtml(row.time)}</td><td>${escapeHtml(row.detail)}</td><td>${escapeHtml(row.actor)}</td></tr>`)):emptyState('No correction has been published.'),button('Close','primary','data-action="close-modal"'));return;}
    if(action==='roadmap-open-day'){state.selectedResourceId=id;renderRoadmapDay(Number(node.dataset.day||1));return;}if(action==='roadmap-complete-day'){const map=moduleRecordV25('roadmap',id),day=Number(node.dataset.day||1);modulesV25.student.roadmapCurrentDay[id]=Math.min(map.durationDays,day+1);modulesV25.student.roadmapProgress[id]=Math.max(Number(modulesV25.student.roadmapProgress[id]||0),Math.round(day/map.durationDays*100));const row=map.days.find(item=>item.day===day);if(row)row.status='Complete';persistModulesV25();adapter.recordRoadmapProgress?.({resourceId:id,resourceType:'roadmap',day,progress:modulesV25.student.roadmapProgress[id]}).catch?.(error=>lp4OperationFailure('recordRoadmapProgress',error));renderRoadmapDay(modulesV25.student.roadmapCurrentDay[id]);toast(`Day ${day} completed`,'✓');return;}if(action==='roadmap-week'){const map=moduleRecordV25('roadmap',id),week=Number(node.dataset.week||1),day=(week-1)*7+1;modulesV25.student.roadmapCurrentDay[id]=Math.min(day,map.durationDays);persistModulesV25();renderRoadmapWorkspace(resourceById(id));return;}if(action==='roadmap-catchup'){openModal('Catch-up plan','Missed days are reorganised without silently marking work complete.',`<div class="dashboard-grid">${infoCard('Current day',String(roadmapCurrentDayV25(id)))}${infoCard('Suggested recovery','One required task today + one optional task tomorrow')}${infoCard('Mentor checkpoint','Available when the learner remains behind for 3 days')}</div>`,button('Apply catch-up plan','primary','data-action="close-modal"'));return;}if(action==='roadmap-reschedule'||action==='roadmap-calendar'){if(action==='roadmap-reschedule')adapter.rescheduleRoadmap?.({resourceId:id,resourceType:'roadmap',currentDay:roadmapCurrentDayV25(id)}).catch?.(error=>lp4OperationFailure('rescheduleRoadmap',error));toast(action==='roadmap-calendar'?'Roadmap calendar prepared':'Roadmap reschedule request saved','⇢');return;}
    if(action==='live-join'){openLiveJoinV25(moduleRecordV25('live',id));return;}if(action==='live-readiness'){adapter.saveLiveReminder?.({sessionId:id,resourceId:id,resourceType:'live',kind:'preparation'}).catch?.(error=>lp4OperationFailure('saveLivePreparation',error));openModal('Live readiness check','Account, access, device and provider readiness.',`<div class="dashboard-grid">${infoCard('Identity','Verified learner account')}${infoCard('Access','Exact session access checked')}${infoCard('Microphone & camera','Provider device test required')}${infoCard('Connection','Recommended stable broadband')}</div>`,button('Done','primary','data-action="close-modal"'));return;}if(action==='live-reminder'){if(!modulesV25.student.liveReminders.includes(id))modulesV25.student.liveReminders.push(id);persistModulesV25();adapter.saveLiveReminder?.({sessionId:id,resourceType:'live'}).catch?.(error=>lp4OperationFailure('saveLiveReminder',error));toast('Live reminder saved','◷');return;}if(action==='live-calendar'){if(!modulesV25.student.calendar.includes(id))modulesV25.student.calendar.push(id);persistModulesV25();adapter.saveLiveReminder?.({sessionId:id,resourceId:id,resourceType:'live',kind:'calendar'}).catch?.(error=>lp4OperationFailure('saveLiveCalendar',error));toast('Session added to AspireNest calendar','▦');return;}if(action==='calendar-export'){toast('Calendar export prepared; production adapter creates ICS','▦');return;}if(action==='mentor-live-create'){openModuleBuilderV25('live');return;}
  },true);



  // LP4 production-state reconciliation. Local storage is UX cache only; server truth wins when available.
  function lp4OperationFailure(method,error){
    const code=String(error?.code||error?.reasonCode||error?.message||'operation_failed');
    console.warn('[LP4]',method,code);
    try{toast(`Server sync failed: ${method}. Reload to reconcile.`, '!');}catch(_){}
    return null;
  }
  async function hydrateLp4ProductionState(){
    if(!state.session?.authenticated)return;
    try{
      const progress=await adapter.recordProgress?.({mode:'load',resourceType:'note'});
      const items=progress?.state?.items||progress?.items||[];
      for(const item of items){
        const id=String(item.resourceId||'');if(!id)continue;
        const type=String(item.resourceType||'');const p=Math.max(0,Math.min(100,Number(item.progress)||0));
        if(type==='note'){noteV24.progressByResource[id]=p;const r=resourceById(id);if(r)r.progress=p;}
        if(type==='video'||type==='replay'){modulesV25.student.videoProgress[id]=p;if(id===state.selectedResourceId)state.videoProgress=p;}
        if(type==='current-affairs')modulesV25.student.caProgress[id]=p;
        if(type==='roadmap')modulesV25.student.roadmapProgress[id]=p;
      }
      if(items.length){persistNotesV24();persistModulesV25();persistPlayerState();}
    }catch(error){lp4OperationFailure('hydrate-progress',error);}
    try{
      const hub=await adapter.loadStudentRevisionHub?.({});
      const catalog=hub?.state?.catalog||hub?.catalog||[],learning=hub?.state?.learning||hub?.learning||[];
      if(Array.isArray(catalog)){for(const remote of catalog){const id=String(remote.resourceId||remote.id||'');if(!id)continue;const local=resourceById(id);if(local){for(const key of ['title','subtitle','description','subject','requiredPlan','status','canonicalRoute','duration','startAt','endAt','timezone','mentorName'])if(remote[key]!==undefined)local[key]=remote[key];local.recent=false;}}}
      state.saved.clear();
      for(const item of learning){const id=String(item.resourceId||'');if(!id)continue;const local=resourceById(id);if(!local)continue;if(item.saved===true)state.saved.add(id);local.recent=Number(item.recentAtMs||0)>0;const p=Math.max(0,Math.min(100,Number(item.progress)||0));local.progress=p;if(item.cursor&&typeof item.cursor==='object'){if(local.type==='note'&&Number.isFinite(Number(item.cursor.page)))state.reader.byResource[id]={...(state.reader.byResource[id]||{}),page:Number(item.cursor.page)};if((local.type==='video'||local.type==='replay')&&Number.isFinite(Number(item.cursor.seconds)))modulesV25.student.videoProgress[id]=p;if(local.type==='roadmap'&&Number.isFinite(Number(item.cursor.day)))modulesV25.student.roadmapCurrentDay[id]=Math.max(1,Number(item.cursor.day));}}
      persistSets();
    }catch(error){lp4OperationFailure('hydrate-discovery',error);}
    try{
      const roads=await adapter.loadRoadmapProgress?.({});
      const items=roads?.state?.items||roads?.items||[];
      for(const item of items){const id=String(item.resourceId||'');if(!id)continue;modulesV25.student.roadmapProgress[id]=Math.max(0,Math.min(100,Number(item.progress)||0));modulesV25.student.roadmapCurrentDay[id]=Math.max(1,Number(item.day||1));}
      if(items.length)persistModulesV25();
    }catch(error){lp4OperationFailure('hydrate-roadmaps',error);}
  }

  // --------------------------------------------------------------------------
  // V25.1 completion hardening — role-aware details, provider gates, timezone,
  // authoring utilities and operational insight without exposing credentials.
  // --------------------------------------------------------------------------
  function normalizeWallClockV25(value,timeZone='Asia/Kolkata'){const text=String(value||'').trim();if(!text)return '';if(/[zZ]$|[+-]\d{2}:?\d{2}$/.test(text))return text;const base=text.length===16?`${text}:00`:text;return timeZone==='Asia/Kolkata'?`${base}+05:30`:timeZone==='UTC'?`${base}Z`:base;}
  function formatDateTimeV25(value,timeZone='Asia/Kolkata',options={}){
    const date=value instanceof Date?value:new Date(value);if(Number.isNaN(date.getTime()))return 'Not scheduled';
    return new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone,...options}).format(date);
  }
  function liveGateV25(record,at=Date.now()){
    const start=new Date(record.startAt).getTime(),end=new Date(record.endAt).getTime(),open=start-Number(record.joinWindowMinutes||10)*60000,late=start+Number(record.lateJoinMinutes||20)*60000;
    if(record.status==='Cancelled')return {state:'cancelled',canJoin:false,label:'Cancelled',detail:'The session was cancelled by Admin.'};
    if(at<open)return {state:'upcoming',canJoin:false,label:'Upcoming',detail:`Join opens ${record.joinWindowMinutes||10} minutes before the scheduled start.`};
    if(at>=open&&at<=late)return {state:'join-window',canJoin:true,label:'Join window',detail:'Identity and exact access will be checked before the provider opens.'};
    if(at>late&&at<=end)return {state:'late-live',canJoin:true,label:'Live now',detail:'Late join is allowed while the session remains active.'};
    return {state:'ended',canJoin:false,label:record.replayResourceId?'Replay available':'Ended',detail:record.replayResourceId?'Open the reviewed replay after access verification.':'This session has ended.'};
  }
  function moduleDetailFactsV25(type,record){
    if(type==='video')return [['Source',record.sourceType.replace(/_/g,' ')],['Visibility',record.visibility],['Duration',`${record.durationMinutes} min`],['Preview',`${record.previewSeconds||0} sec`],['Captions',record.captionsEnabled?(record.captionLanguages||[]).join(', '):'Off'],['Transcript',record.transcriptEnabled?'Enabled':'Off'],['Chapters',String((record.chapters||[]).length)],['Attachments',String((record.attachments||[]).length)],['Completion',`${record.completionThreshold||90}%`],['Download',record.downloadEnabled?'Allowed':'Protected']];
    if(type==='live'){const gate=liveGateV25(record);return [['Provider',record.providerType.replace(/_/g,' ')],['When',formatDateTimeV25(record.startAt,record.timezone)],['Timezone',record.timezone],['Join state',gate.label],['Join window',`${record.joinWindowMinutes} min before`],['Late join',`${record.lateJoinMinutes} min`],['Capacity',String(record.capacity)],['Attendance',record.attendanceEnabled?'Enabled':'Off'],['Recording',record.recordingPolicy.replace(/_/g,' ')],['Replay',record.replayPolicy.replace(/_/g,' ')],['Public listing',record.publicListing],['Backup',record.backupProvider.replace(/_/g,' ')]];}
    if(type==='current-affairs')return [['Edition',record.editionType],['Issue date',record.issueDate],['Coverage',`${record.coverageStart||'—'} → ${record.coverageEnd||'—'}`],['Sources',`${(record.sources||[]).filter(x=>x.verified).length}/${(record.sources||[]).length} verified`],['Pages',String((record.pages||[]).length)],['Categories',(record.categories||[]).join(', ')],['Quiz',record.quizEnabled?'Enabled':'Off'],['Revision',record.revisionEnabled?'Enabled':'Off'],['Public preview',`${record.publicPreviewPages||0} page(s)`],['Corrections',String((record.corrections||[]).length)]];
    return [['Duration',`${record.durationDays} days`],['Cadence',record.cadence],['Start mode',record.startMode.replace(/_/g,' ')],['Day records',String((record.days||[]).length)],['Weeks',String((record.weeks||[]).length)],['Milestones',String((record.milestones||[]).length)],['Catch-up',record.allowCatchUp?'Enabled':'Off'],['Reschedule',record.allowReschedule?'Enabled':'Off'],['Mentor checkpoints',record.mentorCheckpoints?'Enabled':'Off'],['Completion',record.completionRule.replace(/_/g,' ')]];
  }
  function moduleDetailsBodyV25(type,record,resource){
    const publicView=state.role==='public',gate=type==='live'?liveGateV25(record):null;
    const publicNote=type==='live'?'Join URL, meeting ID, passcode and unlisted provider URLs remain hidden until identity, entitlement and join-window checks pass.':type==='video'?'The protected playback URL is never exposed in Public discovery. Listed/unlisted is a provider setting; AspireNest access remains authoritative.':type==='current-affairs'?'Public preview follows the configured page limit. Full IntelliBook content requires exact access.':'Each linked task independently checks access; a Roadmap never silently unlocks a Note, Video, Test or Live session.';
    return `<section class="module-v25-public-detail type-${type}"><header><span class="module-v25-icon">${providerIconV25(type==='video'?record.sourceType:type==='live'?record.providerType:type)}</span><div><span class="eyebrow">${escapeHtml(type.toUpperCase().replace('-',' '))} • ${escapeHtml(record.id)}</span><h2>${escapeHtml(record.title)}</h2><p>${escapeHtml(record.description)}</p></div>${validationBadgeV25(record)}</header><div class="resource-detail-facts-v23">${moduleDetailFactsV25(type,record).map(([label,value])=>`<span><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`).join('')}</div>${gate?`<div class="continuity-note"><strong>${escapeHtml(gate.label)}</strong><p>${escapeHtml(gate.detail)}</p></div>`:''}<div class="continuity-note"><strong>${publicView?'Public protection boundary':'Exact resource continuity'}</strong><p>${escapeHtml(publicNote)}</p></div></section>`;
  }
  const previewResourceV25Base=previewResource;
  previewResource=function(resource){
    const type=moduleTypeForResourceV25(resource);if(!type)return previewResourceV25Base(resource);const record=moduleRecordV25(type,resource.id);if(!record)return previewResourceV25Base(resource);state.selectedResourceId=resource.id;
    const locked=resource.accessState==='locked'||resource.accessState==='expired';let primary=locked?'Request Access':type==='video'?'Open IntelliPlayer':type==='live'?'View Live Session':type==='current-affairs'?'Open IntelliBook':'Open Roadmap';let action=locked?'request-access':'open';
    openModal(resource.title,state.role==='public'?'Public module preview with protected delivery and exact-resource continuity.':`${state.role[0].toUpperCase()+state.role.slice(1)} module details and next safe action.`,moduleDetailsBodyV25(type,record,resource),`${button('Close','secondary','data-action="close-modal"')}${button(primary,'primary',`data-resource-action-v23="${action}" data-id="${resource.id}"`)}`);
  };

  function moduleOpsPanelV25(type,records){
    if(type==='video'){const chapters=records.reduce((n,r)=>n+(r.chapters||[]).length,0),captioned=records.filter(r=>r.captionsEnabled).length,hosted=records.filter(r=>r.sourceType==='HOSTED_STREAM').length;return `<section class="module-v25-ops-panel"><header><div><span class="eyebrow">VIDEO OPERATIONS</span><h2>Delivery, processing and learning intelligence</h2></div></header><div class="module-v25-ops-grid">${infoCard('Provider mix',`${hosted} hosted • ${records.length-hosted} linked`)}${infoCard('Caption readiness',`${captioned}/${records.length} enabled`)}${infoCard('Chapter markers',String(chapters))}${infoCard('Protected playback','Signed URL / embed adapter boundary')}</div><div class="continuity-note"><strong>Real media processing boundary</strong><p>Upload, transcode, thumbnail generation, caption files, DRM/signed URLs and provider analytics run through secure backend adapters during repository integration.</p></div></section>`;}
    if(type==='live'){const zoom=records.filter(r=>/ZOOM/.test(r.providerType)).length,youtube=records.filter(r=>/YOUTUBE/.test(r.providerType)).length,recorded=records.filter(r=>r.recordingPolicy!=='NO_RECORDING').length;return `<section class="module-v25-ops-panel"><header><div><span class="eyebrow">LIVE CONTROL</span><h2>Providers, attendance and replay queue</h2></div></header><div class="module-v25-ops-grid">${infoCard('Zoom sessions',String(zoom))}${infoCard('YouTube Live',String(youtube))}${infoCard('Recording enabled',`${recorded}/${records.length}`)}${infoCard('Protected join','Identity + access + time gate')}</div><div class="module-v25-provider-matrix"><article><strong>Zoom OAuth/API</strong><span class="state-badge partial">Prepared • Disabled</span><p>Meeting create/update, registrants and attendance adapter.</p></article><article><strong>YouTube Live API</strong><span class="state-badge partial">Prepared • Disabled</span><p>Listed/unlisted broadcast, stream binding and replay adapter.</p></article><article><strong>External URL</strong><span class="state-badge open">Configuration ready</span><p>HTTPS validation with protected redirect boundary.</p></article></div></section>`;}
    if(type==='current-affairs'){const verified=records.reduce((n,r)=>n+(r.sources||[]).filter(x=>x.verified).length,0),pages=records.reduce((n,r)=>n+(r.pages||[]).length,0);return `<section class="module-v25-ops-panel"><header><div><span class="eyebrow">EDITORIAL CONTROL</span><h2>Source verification, IntelliText and corrections</h2></div></header><div class="module-v25-ops-grid">${infoCard('Verified sources',String(verified))}${infoCard('IntelliText pages',String(pages))}${infoCard('Corrections',String(records.reduce((n,r)=>n+(r.corrections||[]).length,0)))}${infoCard('Revision packages',String(records.filter(r=>r.revisionEnabled).length))}</div></section>`;}
    const days=records.reduce((n,r)=>n+(r.days||[]).length,0),links=records.reduce((n,r)=>n+(r.days||[]).reduce((x,d)=>x+(d.resourceIds||[]).length,0),0);return `<section class="module-v25-ops-panel"><header><div><span class="eyebrow">ASPIREPATH CONTROL</span><h2>Day plans, exact resources and mentor checkpoints</h2></div></header><div class="module-v25-ops-grid">${infoCard('Day records',String(days))}${infoCard('Exact resource links',String(links))}${infoCard('Milestones',String(records.reduce((n,r)=>n+(r.milestones||[]).length,0)))}${infoCard('Catch-up enabled',String(records.filter(r=>r.allowCatchUp).length))}</div></section>`;
  }
  const renderModuleAdminV25Base=renderModuleAdminV25;
  renderModuleAdminV25=function(type){renderModuleAdminV25Base(type);const workflow=els.page.querySelector('.module-v25-workflow');if(workflow)workflow.insertAdjacentHTML('afterend',moduleOpsPanelV25(type,Object.values(moduleCollectionV25(type))));};

  const moduleMoreV25Base=moduleMoreV25;
  moduleMoreV25=function(type,record){
    const extras=type==='video'?`<button data-v25-action="video-processing-report" data-type="video" data-id="${record.id}">Processing & delivery report</button>`:type==='live'?`<button data-v25-action="live-provider-report" data-type="live" data-id="${record.id}">Provider readiness report</button>`:type==='current-affairs'?`<button data-v25-action="ca-edit-pages" data-type="current-affairs" data-id="${record.id}">Edit IntelliText pages</button><button data-v25-action="ca-add-correction" data-type="current-affairs" data-id="${record.id}">Publish correction note</button>`:`<button data-v25-action="roadmap-day-report" data-type="roadmap" data-id="${record.id}">Day & link report</button>`;
    openModal('More operations','Soft-retained module operations.',`<section class="module-v25-more">${extras}<button data-v25-action="module-duplicate" data-type="${type}" data-id="${record.id}">Duplicate as draft</button><button data-v25-action="module-validate-record" data-type="${type}" data-id="${record.id}">Validate now</button><button data-v25-action="module-audit-record" data-type="${type}" data-id="${record.id}">View audit history</button><button data-v25-action="${moduleStatusV25(record)==='Archived'?'module-restore':'module-archive'}" data-type="${type}" data-id="${record.id}">${moduleStatusV25(record)==='Archived'?'Restore as draft':'Archive'}</button></section>`,button('Close','secondary','data-action="close-modal"'));
  };
  function openCaPageEditorV25(record){
    openModal('Current Affairs IntelliText editor','Edit exact page identity and content. Source register remains attached to the issue.',`<form id="caPageEditorV25" data-id="${record.id}" class="module-v25-ca-editor">${(record.pages||[]).map((page,index)=>`<article><header><span>${index+1}</span><strong>Page ${index+1}</strong></header><label>Title<input name="title-${index}" value="${escapeHtml(page.title||'')}"></label><label>Paragraphs<textarea name="paragraphs-${index}">${escapeHtml((page.paragraphs||[]).join('\n\n'))}</textarea></label><label>Bullets<textarea name="bullets-${index}">${escapeHtml((page.bullets||[]).join('\n'))}</textarea></label><label>Exam callout<textarea name="callout-${index}">${escapeHtml(page.callout||'')}</textarea></label></article>`).join('')}</form>`,`${button('Cancel','secondary','data-action="close-modal"')}${button('Save IntelliText pages','primary',`data-v25-action="ca-save-pages" data-id="${record.id}"`)}`);
  }
  function saveCaPagesV25(record){const form=document.getElementById('caPageEditorV25');if(!form)return;(record.pages||[]).forEach((page,index)=>{page.title=String(form.elements[`title-${index}`]?.value||page.title);page.paragraphs=String(form.elements[`paragraphs-${index}`]?.value||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);page.bullets=String(form.elements[`bullets-${index}`]?.value||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);page.callout=String(form.elements[`callout-${index}`]?.value||'');page.number=index+1;});record.updatedAt=nowV25();record.validation=moduleValidationV25('current-affairs',record);moduleAuditV25('EDIT_INTELLITEXT','current-affairs',record.id,`${record.pages.length} pages`);adapter.saveCurrentAffairsPages?.({resourceId:record.id,resourceType:'current-affairs',pages:cloneV25(record.pages)}).catch?.(error=>lp4OperationFailure('saveCurrentAffairsPages',error));persistModulesV25();closeModal();renderModuleAdminV25('current-affairs');toast('Current Affairs IntelliText pages saved','✓');}
  function openCorrectionEditorV25(record){openModal('Publish correction note','Corrections are appended to the audit trail and never silently overwrite the original source record.',`<form id="caCorrectionV25"><label class="module-v25-field wide"><span>Correction / clarification</span><textarea name="detail" required minlength="10"></textarea></label></form>`,`${button('Cancel','secondary','data-action="close-modal"')}${button('Publish correction','primary',`data-v25-action="ca-save-correction" data-id="${record.id}"`)}`);}
  function saveCorrectionV25(record){const form=document.getElementById('caCorrectionV25');if(!form||!form.reportValidity())return;const detail=String(new FormData(form).get('detail'));record.corrections=record.corrections||[];record.corrections.unshift({time:nowV25(),detail,actor:state.session.email||'Admin'});record.version=Number(record.version||0)+1;record.updatedAt=nowV25();moduleAuditV25('PUBLISH_CORRECTION','current-affairs',record.id,detail);adapter.publishCurrentAffairsCorrection?.({resourceId:record.id,resourceType:'current-affairs',correction:cloneV25(record.corrections[0])}).catch?.(error=>lp4OperationFailure('publishCurrentAffairsCorrection',error));persistModulesV25();closeModal();renderModuleAdminV25('current-affairs');toast('Correction note published','✓');}
  function openModuleReportV25(type,record){
    let body='';if(type==='video')body=`<div class="module-v25-provider-matrix"><article><strong>Source</strong><span class="state-badge open">${escapeHtml(record.sourceType.replace(/_/g,' '))}</span><p>${safeUrlV25(record.sourceUrl)?'Provider URL validates as HTTPS.':'Protected Storage path prepared.'}</p></article><article><strong>Captions & transcript</strong><span class="state-badge ${record.captionsEnabled&&record.transcriptEnabled?'open':'partial'}">${record.captionsEnabled&&record.transcriptEnabled?'Ready':'Review'}</span><p>${escapeHtml((record.captionLanguages||[]).join(', ')||'No languages configured')}</p></article><article><strong>Playback protection</strong><span class="state-badge partial">Adapter boundary</span><p>Signed/authorised playback activates with the production media service.</p></article></div>`;
    else if(type==='live'){const gate=liveGateV25(record);body=`<div class="module-v25-provider-matrix"><article><strong>Primary provider</strong><span class="state-badge open">${escapeHtml(record.providerType.replace(/_/g,' '))}</span><p>${safeUrlV25(record.joinUrl)?'Valid HTTPS join/watch URL.':'Invalid provider URL.'}</p></article><article><strong>Backup provider</strong><span class="state-badge ${record.backupProvider==='NONE'?'partial':'open'}">${escapeHtml(record.backupProvider.replace(/_/g,' '))}</span><p>${record.backupProvider==='NONE'?'No backup configured.':safeUrlV25(record.backupUrl)?'Backup URL validates.':'Backup URL requires review.'}</p></article><article><strong>Current gate</strong><span class="state-badge ${gate.canJoin?'open':'partial'}">${escapeHtml(gate.label)}</span><p>${escapeHtml(gate.detail)}</p></article></div>`;}
    else {const missing=[];(record.days||[]).forEach(day=>(day.resourceIds||[]).forEach(id=>{if(!resourceById(id))missing.push(`Day ${day.day}: ${id}`);}));body=`<div class="module-v25-ops-grid">${infoCard('Configured days',String((record.days||[]).length))}${infoCard('Duration',String(record.durationDays))}${infoCard('Missing links',String(missing.length))}${infoCard('Mentor checkpoints',String((record.days||[]).filter(d=>d.mentorCheckpoint).length))}</div>${missing.length?`<ul>${missing.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`:'<div class="continuity-note"><strong>All exact resource links resolve.</strong><p>Entitlement remains independently checked when each task opens.</p></div>'}`;}
    openModal(type==='video'?'Video processing & delivery':type==='live'?'Live provider readiness':'Roadmap day & link report','Operational report without exposing provider credentials.',body,button('Close','primary','data-action="close-modal"'));
  }

  const openLiveJoinV25Base=openLiveJoinV25;
  openLiveJoinV25=async function(record){
    const gate=liveGateV25(record);
    if(!gate.canJoin){openModal(gate.label,'The provider cannot open at this time.',`<div class="continuity-note"><strong>${escapeHtml(formatDateTimeV25(record.startAt,record.timezone))}</strong><p>${escapeHtml(gate.detail)}</p></div>`,`${button('Close','secondary','data-action="close-modal"')}${record.replayResourceId&&gate.state==='ended'?button('Open replay','primary',`data-open="${record.replayResourceId}"`):button('Set reminder','primary',`data-v25-action="live-reminder" data-id="${record.id}"`)}`);return;}
    try{
      const resolved=await adapter.resolveLiveJoin?.({sessionId:record.id,resourceType:'live',providerType:record.providerType});
      const secureUrl=resolved?.state?.joinUrl||resolved?.joinUrl||'';
      if(!resolved?.ok||!safeUrlV25(secureUrl))throw new Error(resolved?.code||'SERVER_JOIN_DENIED');
      const secureRecord={...record,joinUrl:secureUrl};
      const attendance=await adapter.recordLiveAttendance?.({sessionId:record.id,resourceType:'live',event:'JOIN_REQUEST'});
      if(attendance&&attendance.ok===false)throw new Error(attendance.code||'ATTENDANCE_REJECTED');
      return openLiveJoinV25Base(secureRecord);
    }catch(error){lp4OperationFailure('resolveLiveJoin',error);openModal('Live join unavailable','The server could not verify this join request. No provider URL was opened.',`<div class="continuity-note"><strong>Protected join denied</strong><p>Refresh and try again. Access and the join window are rechecked on every request.</p></div>`,button('Close','primary','data-action="close-modal"'));return;}
  };
  const renderLiveWorkspaceV25TimeBase=renderLiveWorkspace;
  renderLiveWorkspace=function(resource){renderLiveWorkspaceV25TimeBase(resource);const record=moduleRecordV25('live',resource?.id);if(!record)return;const intro=els.page.querySelector('.module-v25-live-hero > div > div > p');if(intro)intro.textContent=`${formatDateTimeV25(record.startAt,record.timezone)} • ${record.mentorName} • ${record.access}`;const gate=liveGateV25(record),aside=els.page.querySelector('.module-v25-live-hero aside');if(aside)aside.setAttribute('data-live-gate',gate.state);};
  const renderLiveV25TimeBase=renderLive;
  renderLive=function(context){renderLiveV25TimeBase(context);if(context==='upcoming'){const records=Object.values(modulesV25.live);[...els.page.querySelectorAll('.module-v25-live-list > article')].forEach((card,index)=>{const p=card.querySelector('header p'),record=records[index];if(p&&record)p.textContent=`${formatDateTimeV25(record.startAt,record.timezone)} • ${record.mentorName}`;});}if(context==='calendar'){const records=Object.values(modulesV25.live);[...els.page.querySelectorAll('.module-v25-calendar article')].forEach((card,index)=>{if(index<records.length){const p=card.querySelector('p');if(p)p.textContent=formatDateTimeV25(records[index].startAt,records[index].timezone);}});}};


